function tq(stem,...choices){return {stem,options:choices.map(c=>{const [text,why]=c.slice(1).split(' ~ ');return {text,correct:c[0]==='+',why}})}}
const diseaseLessons=[];
function disease(id,name,system,slug,definition,signs,care,warning,items){const source='d-'+id;trainerSources[source]=['NHS · '+name,'https://www.nhs.uk/conditions/'+slug+'/'];diseaseLessons.push({id,name,system,definition,signs:signs.split('|'),care:care.split('|'),warning,sources:[source],items:items.map((v,i)=>({...v,id:'d-'+id+'-'+(i+1),kind:'disease',group:id,sources:[source],level:i<2?'Verstehen':'Anwenden'}))})}
disease('copd','COPD','Atmung','chronic-obstructive-pulmonary-disease-copd','Chronische Lungenerkrankung mit anhaltender Atemwegsverengung; Exazerbation bedeutet akute Verschlechterung.','Belastungsatemnot|Husten mit Auswurf, teils Giemen|Bei Verschlechterung mehr Atemnot oder verändertes Sputum','Atemarbeit, Atemfrequenz, Bewusstsein und SpO₂ im Verlauf beurteilen|Atemerleichternde Position, Inhalationstechnik und verordnete Therapie unterstützen|Sauerstoff kontrolliert nach Zielbereich und Standard; bei Hyperkapnierisiko häufig 88–92 %, individuell prüfen','Schläfrigkeit und nachlassende Atemtiefe können Atemversagen anzeigen. Sauerstoff bei Hypoxämie nicht pauschal verweigern.',[
 tq('Welche Befunde passen zu einer COPD?','+Belastungsatemnot ~ Eine eingeschränkte Ventilation vermindert Belastbarkeit.','+Anhaltender Husten mit Auswurf ~ Häufig bei chronischer Bronchitis.','-Immer vollständige Beschwerdefreiheit nach Antibiotika ~ COPD bleibt eine chronische Erkrankung.','-Ausschließlich plötzlich einsetzender Brustschmerz ~ Das erklärt COPD nicht typisch.'),
 tq('Was bedeutet eine Exazerbation?','+Akute Verschlechterung der üblichen Beschwerden ~ Sie erfordert erneute Beurteilung.','-Eine dauerhafte Heilung ~ Exazerbation bezeichnet Verschlechterung.','-Eine ausschließlich radiologische Diagnose ~ Symptome und Verlauf sind wesentlich.','-Jede einzelne Hustenbewegung ~ Entscheidend ist die Veränderung zum Ausgangszustand.'),
 tq('Eine COPD-Patientin wird schläfrig und atmet flacher. Welche Schritte sind angemessen?','+Sofort Hilfe holen und strukturiert beurteilen ~ Respiratorisches Versagen muss abgeklärt werden.','+Blutgasanalyse im Behandlungsteam veranlassen ~ SpO₂ misst keine CO₂-Retention.','-Die niedrigere Atemfrequenz als sichere Besserung werten ~ Erschöpfung kann die Atmung abschwächen.','-Sauerstoff grundsätzlich vollständig abstellen ~ Hypoxämie muss kontrolliert behandelt werden.'),
 tq('Was gehört zur Vorbereitung einer sicheren Entlassung bei COPD?','+Inhalation vorführen lassen ~ Anwendung überprüfen statt nur fragen.','+Individuellen Plan für Verschlechterungen besprechen ~ Frühes Reagieren unterstützt Selbstmanagement.','-Allen dieselbe Sauerstoffmenge verordnen ~ Zielbereiche und Verordnung sind individuell.','-Körperliche Aktivität grundsätzlich verbieten ~ Angepasste Aktivität ist Teil der Versorgung.')]);
disease('asthma','Asthma bronchiale','Atmung','asthma','Chronisch entzündliche Atemwegserkrankung mit variabler Atemwegsverengung und wechselnden Beschwerden.','Anfallsweise Atemnot und Engegefühl|Giemen und Husten, teils nachts|Beschwerden können durch Allergene oder Belastung ausgelöst werden','Atemnot einschätzen und Auslöser erfragen|Inhalationstechnik und persönlichen Behandlungsplan überprüfen|Bei schwerem Anfall Hilfe und Akuttherapie nach Notfallplan','Kaum hörbare Atemgeräusche bei schwerer Atemnot können eine bedrohlich geringe Luftbewegung bedeuten.',[
 tq('Welche Beschwerden passen zu Asthma?','+Anfallsweises Giemen ~ Eine variable Obstruktion ist typisch.','+Nächtlicher Husten ~ Asthma kann nachts stärker auffallen.','-Immer hohes Fieber ~ Fieber ist kein notwendiges Asthmakriterium.','-Dauerhaft fehlender Puls ~ Das beschreibt einen Kreislaufnotfall.'),
 tq('Welche Aussage zur Asthmatherapie trifft zu?','+Der individuelle Inhalations- und Notfallplan ist maßgeblich ~ Präparat und Regime unterscheiden sich.','-Jedes Asthmaspray hat dieselbe Aufgabe ~ Bedarfs- und Dauertherapie können sich unterscheiden.','-Beschwerdefreiheit erlaubt immer sofortiges Absetzen ~ Änderungen benötigen fachliche Abstimmung.','-Inhalationstechnik ist unwichtig ~ Fehler können die Wirkstoffaufnahme verringern.'),
 tq('Ein Patient kann wegen Atemnot kaum sprechen. Das Giemen wird leiser, er erschöpft. Was folgt?','+Unverzüglich Notfallhilfe und ABCDE ~ Erschöpfung ist ein Warnsignal.','+Akutmedikation nach gültigem Notfallplan unterstützen ~ Die Versorgung darf nicht verzögert werden.','-Leisere Atmung als sichere Entspannung bewerten ~ Weniger Luftbewegung kann gefährlich sein.','-Zur Beruhigung in eine Tüte atmen lassen ~ Das ist bei Asthma ungeeignet.'),
 tq('Wie überprüfst du Asthmaschulung sinnvoll?','+Die Person demonstriert die Inhalation ~ Dadurch werden Anwendungsfehler sichtbar.','+Sie erklärt ihre Schritte bei Verschlechterung ~ Das prüft handlungsbezogenes Verständnis.','-Nur fragen: Alles verstanden? ~ Eine Ja-Antwort belegt keinen Lernerfolg.','-Allen ein identisches Gerät empfehlen ~ Auswahl und Einweisung sind individuell.')]);
disease('pneumonia','Pneumonie','Atmung','pneumonia','Entzündung des Lungengewebes, meist durch eine Infektion.','Husten, Fieber und Atemnot|Atemabhängige Schmerzen möglich|Ältere Menschen können neu verwirrt sein','Atmung, Temperatur, Kreislauf und Bewusstsein beurteilen|Schmerztherapie, angepasste Bewegung und ausreichende Versorgung unterstützen|Verordnete Antiinfektiva geben und Wirkung beobachten','Neue Verwirrtheit, zunehmende Atemnot oder Kreislaufstörung können eine schwere Infektion anzeigen.',[
 tq('Welche Befunde können bei Pneumonie auftreten?','+Husten und Atemnot ~ Entzündung beeinträchtigt den Gasaustausch.','+Neue Verwirrtheit im höheren Alter ~ Das kann eine atypische Präsentation sein.','-Ohne Fieber ist Pneumonie ausgeschlossen ~ Fieber kann insbesondere im Alter fehlen.','-Jede Pneumonie ist rein bakteriell ~ Auch Viren können ursächlich sein.'),
 tq('Welche Information ist für die Pflegeplanung besonders hilfreich?','+Atemfrequenz, Bewusstsein und Belastbarkeit im Verlauf ~ Veränderungen zeigen Dringlichkeit und Unterstützungsbedarf.','-Nur eine einmalige Temperatur als vollständige Beurteilung ~ Atmung und Kreislauf bleiben unbewertet.','-Allein der Name des Antibiotikums ~ Er beschreibt den aktuellen Zustand nicht.','-Eine normale SpO₂ schließt jede Verschlechterung aus ~ Weitere Vitalwerte und Symptome sind nötig.'),
 tq('Eine Patientin mit Pneumonie wird verwirrt und kreislaufinstabil. Was ist angemessen?','+Sofortige strukturierte Beurteilung und Eskalation ~ Eine Sepsis oder Ateminsuffizienz ist möglich.','+Aktuelle Vitalwerte strukturiert übermitteln ~ Das unterstützt die dringliche Behandlung.','-Bis zur nächsten Routinevisite warten ~ Zustandsverschlechterung ist zeitkritisch.','-Nur Schlaf anbieten ~ Ursachenabklärung bleibt erforderlich.'),
 tq('Welche Maßnahmen sind individuell zu planen?','+Mobilisation entsprechend Kreislauf und Belastbarkeit ~ Bewegung muss sicher und angepasst erfolgen.','+Flüssigkeitsversorgung unter Beachtung von Begleiterkrankungen ~ Herz- oder Nierenprobleme können Grenzen setzen.','-Jeder Person mehrere Liter zusätzlich aufzwingen ~ Eine pauschale Menge ist ungeeignet.','-Schmerzmittel vorenthalten, damit Husten schmerzt ~ Schmerz kann tiefes Atmen erschweren.')]);
disease('pe','Lungenembolie','Atmung','pulmonary-embolism','Verschluss einer Lungenarterie, meist durch ein eingeschwemmtes Blutgerinnsel.','Plötzliche Atemnot|Atemabhängiger Brustschmerz und Tachykardie|Synkope oder Bluthusten möglich','Sofortige Notfallbeurteilung bei Verdacht|Belastung vermeiden, begleiten und Vitalfunktionen überwachen|Diagnostik und angeordnete Therapie unterstützen','Akute Atemnot nach Immobilisation oder mit einseitiger Beinschwellung ist dringlich abzuklären.',[
 tq('Welche Befunde begründen einen Lungenembolieverdacht?','+Plötzliche Atemnot mit Brustschmerz ~ Diese Kombination ist ein Warnsignal.','+Synkope nach längerer Immobilisation ~ Ein relevantes Thromboembolierisiko liegt vor.','-Langjähriger unveränderter Nagelpilz ~ Das ist kein typischer Akutbefund.','-Nur eine SpO₂ von 98 % schließt sie sicher aus ~ Ein einzelner Wert reicht zum Ausschluss nicht.'),
 tq('Woher stammt ein Embolus häufig?','+Aus einer tiefen Venenthrombose ~ Gerinnsel können in die Lungengefäße gelangen.','-Aus Luft in einer intakten Hautblase ~ Das beschreibt diesen Mechanismus nicht.','-Aus einer verstopften Talgdrüse ~ Es besteht kein entsprechender Gefäßweg.','-Aus eingeatmetem Staub als Regelursache ~ Typisch ist ein thrombotischer Gefäßverschluss.'),
 tq('Eine frisch operierte Person hat plötzlich Atemnot und kollabiert beinahe. Was tust du?','+Notfallteam alarmieren und ABCDE anwenden ~ Eine lebensbedrohliche Ursache ist möglich.','+Begleiten und belastungsarme Versorgung organisieren ~ Unbegleitete Belastung ist jetzt ungeeignet.','-Zum Test allein über den Flur laufen lassen ~ Das gefährdet die Person.','-Erst die reguläre Dokumentation abschließen ~ Akutversorgung hat Vorrang.'),
 tq('Was ist unter angeordneter Antikoagulation zu beobachten?','+Blutungszeichen ~ Die Therapie erhöht das Blutungsrisiko.','+Neue Atemnot oder Kreislaufverschlechterung ~ Erneute Verschlechterung verlangt Beurteilung.','-Dosis selbst verdoppeln bei Angst ~ Anpassungen brauchen eine gültige Anordnung.','-Jede Hämatombildung verschweigen ~ Auffälligkeiten sind zu bewerten.')]);
disease('hf','Herzinsuffizienz','Herz und Gefäße','heart-failure','Das Herz kann den Kreislauf nicht bedarfsgerecht versorgen; Blut kann sich zurückstauen.','Atemnot bei Belastung oder im Liegen|Beinödeme und rasche Gewichtszunahme|Müdigkeit und verminderte Belastbarkeit','Gewicht unter vergleichbaren Bedingungen und Symptome verfolgen|Belastung dosieren und Selbstbeobachtung schulen|Flüssigkeit, Diuretika und Kontrollen nach individuellem Behandlungsplan','Akute Atemnot mit schaumigem Auswurf oder Kreislaufstörung ist ein Notfall.',[
 tq('Welche Veränderungen sprechen für zunehmende Stauung?','+Rasche Gewichtszunahme und mehr Beinödeme ~ Flüssigkeitseinlagerung ist möglich.','+Zunehmende Atemnot im Liegen ~ Rückstau kann die Atmung beeinträchtigen.','-Gewichtsabnahme allein beweist Besserung ~ Auch Mangelernährung ist möglich.','-Fehlender Brustschmerz schließt Verschlechterung aus ~ Herzinsuffizienz braucht keinen Brustschmerz.'),
 tq('Welche Aussage beschreibt Herzinsuffizienz am besten?','+Unzureichende Herzfunktion mit möglichen Stauungszeichen ~ Das Herz arbeitet, aber eingeschränkt.','-Das Herz hat definitionsgemäß aufgehört zu schlagen ~ Das wäre ein Kreislaufstillstand.','-Sie betrifft immer nur die linke Herzkammer ~ Unterschiedliche Formen kommen vor.','-Normale Auswurffraktion schließt sie grundsätzlich aus ~ Auch bei erhaltener Auswurffraktion möglich.'),
 tq('Eine Patientin bekommt im Liegen starke Atemnot und rosa-schaumigen Auswurf. Was tust du?','+Notfallhilfe und strukturierte Beurteilung ~ Ein Lungenödem ist möglich.','+Atemerleichternde Position nach Verträglichkeit ~ Sie kann die Atemarbeit erleichtern.','-Große Trinkmenge rasch anbieten ~ Eine Volumenbelastung kann schaden.','-Die nächste Gewichtskontrolle abwarten ~ Die Situation ist akut.'),
 tq('Was gehört zur Beratung bei Herzinsuffizienz?','+Individuelle Warnzeichen und Rückmeldewege vereinbaren ~ Veränderungen sollen früh erkannt werden.','+Diuretikawirkung und Schwindel beobachten ~ Über- und Unterversorgung sind möglich.','-Für alle höchstens 500 ml am Tag festlegen ~ Flüssigkeitsziele sind individuell.','-Dosisänderungen ohne vereinbarten Plan empfehlen ~ Anpassungen brauchen fachliche Abstimmung.')]);
disease('acs','Akutes Koronarsyndrom / Herzinfarkt','Herz und Gefäße','heart-attack','Akute Minderdurchblutung des Herzmuskels; beim Infarkt entsteht Herzmuskeluntergang.','Druck oder Enge im Brustkorb, mögliche Ausstrahlung|Atemnot, Übelkeit und kalter Schweiß|Beschwerden können atypisch oder wenig schmerzhaft sein','Bei Verdacht sofort Notfallversorgung organisieren|Begleiten, Belastung vermeiden, Vitalfunktionen und EKG nach Standard|Therapie nur nach gültiger Anordnung und Kontraindikationsprüfung','Auch ohne typischen Brustschmerz kann ein Infarkt vorliegen.',[
 tq('Welche Kombinationen können auf ein akutes Koronarsyndrom hinweisen?','+Brustdruck mit kaltem Schweiß ~ Das ist eine typische Warnkonstellation.','+Neue Atemnot und Übelkeit bei Risikoperson ~ Atypische Beschwerden sind möglich.','-Kein Brustschmerz bedeutet sicher kein Infarkt ~ Schmerzarmut schließt ihn nicht aus.','-Druckschmerz allein bestätigt den Infarkt ~ Die Diagnose benötigt medizinische Abklärung.'),
 tq('Warum ist rasche Behandlung wichtig?','+Anhaltende Ischämie kann Herzmuskel zerstören ~ Zeit beeinflusst den Gewebeschaden.','+Gefährliche Rhythmusstörungen können auftreten ~ Überwachung ist deshalb bedeutsam.','-Erst Fieber macht einen Infarkt gefährlich ~ Fieber ist keine Voraussetzung.','-Ein einzelner normaler Blutdruck schließt Gefahr aus ~ Er bewertet die Koronardurchblutung nicht.'),
 tq('Eine Person entwickelt anhaltenden Brustdruck und Schweißausbruch. Welche Handlungen sind angemessen?','+Sofort Notfallteam beziehungsweise 112 alarmieren ~ Ein ACS muss rasch abgeklärt werden.','+Bei der Person bleiben und Vitalfunktionen beurteilen ~ Verschlechterung muss erkannt werden.','-Zum Ablaufen des Schmerzes Treppen steigen lassen ~ Belastung kann den Sauerstoffbedarf erhöhen.','-Allein zur Anmeldung schicken ~ Ein Kollaps ist möglich.'),
 tq('Welche Aussage zur pflegerischen Akutversorgung ist richtig?','+Medikamente benötigen Anordnung und Sicherheitsprüfung ~ Kontraindikationen können relevant sein.','-Sauerstoff ist unabhängig von Hypoxämie immer maximal nötig ~ Die Gabe folgt klinischem Zustand und Standard.','-Mit einem selbst ausgewählten Blutverdünner beginnen ~ Eine individuelle Verordnung ist erforderlich.','-Nachlassender Schmerz beendet jede Überwachung ~ Komplikationen können dennoch auftreten.')]);
disease('af','Vorhofflimmern','Herz und Gefäße','atrial-fibrillation','Herzrhythmusstörung mit ungeordneter Vorhofaktivität und häufig unregelmäßiger Kammeraktion.','Unregelmäßiger Puls und Herzklopfen|Schwindel, Atemnot und Leistungsminderung|Auch symptomlose Verläufe möglich','Puls, Blutdruck, Beschwerden und EKG-Abklärung unterstützen|Verordnete Frequenz- oder Rhythmustherapie beobachten|Bei Antikoagulation Blutungszeichen und Einnahmetreue besprechen','Neurologische Ausfälle können auf einen embolischen Schlaganfall hinweisen.',[
 tq('Welche Befunde passen zu Vorhofflimmern?','+Unregelmäßiger Puls ~ Die Kammeraktionen sind häufig unregelmäßig.','+Herzklopfen oder Belastungsintoleranz ~ Diese Beschwerden können auftreten.','-Zwingend dauerhaft über 150 Schläge pro Minute ~ Die Frequenz kann unterschiedlich sein.','-Ein regelmäßiges Pulstasten ersetzt jedes EKG ~ Die Rhythmusdiagnose benötigt weitere Abklärung.'),
 tq('Warum kann Antikoagulation verordnet sein?','+Zur Senkung eines individuell erhöhten Schlaganfallrisikos ~ Gerinnsel aus dem Vorhof können embolisieren.','-Um jeden Puls sofort zu verlangsamen ~ Antikoagulanzien steuern nicht direkt die Frequenz.','-Um jede Blutung zu verhindern ~ Sie erhöhen gerade das Blutungsrisiko.','-Weil alle Menschen dieselbe Dosierung brauchen ~ Präparat und Dosierung sind individuell.'),
 tq('Unter Antikoagulation treten Teerstuhl und Schwindel auf. Was folgt?','+Dringende Beurteilung wegen möglicher Blutung ~ Kreislauf und Blutverlust sind abzuklären.','+Präparat, letzte Einnahme und Symptome übermitteln ~ Das unterstützt sichere Behandlung.','-Als erwartbare harmlose Nebenwirkung ignorieren ~ Eine relevante Blutung ist möglich.','-Die nächste Dosis eigenständig verdoppeln ~ Das könnte die Blutung verstärken.'),
 tq('Ein Patient mit Vorhofflimmern hat plötzlich eine Sprachstörung. Was priorisierst du?','+Schlaganfallnotfall auslösen und Beginn klären ~ Neurologische Ausfälle sind zeitkritisch.','-Nur den Puls eine Stunde zählen ~ Das verzögert die Notfallbehandlung.','-Die Antikoagulation garantiert Schlaganfallfreiheit ~ Sie senkt Risiko, beseitigt es nicht.','-Zur Beruhigung zuerst essen lassen ~ Bei akutem Schlaganfall besteht Dysphagierisiko.')]);
disease('htn','Arterielle Hypertonie','Herz und Gefäße','high-blood-pressure','Dauerhaft erhöhter arterieller Blutdruck; oft lange ohne Beschwerden.','Häufig symptomlos|Langfristiges Risiko für Herz, Gehirn und Nieren|Kopfschmerz allein beweist keine Hypertonie','Mit passender Manschette und standardisierten Bedingungen messen|Verlauf, Therapieadhärenz und Nebenwirkungen erfassen|Individuelle alltagstaugliche Lebensstilziele vereinbaren','Stark erhöhter Blutdruck mit neuen neurologischen Ausfällen, Brustschmerz oder Atemnot verlangt sofortige Abklärung.',[
 tq('Welche Aussage trifft auf Hypertonie zu?','+Sie kann lange unbemerkt bleiben ~ Beschwerden sind kein zuverlässiger Nachweis.','+Sie erhöht langfristig das Gefäßrisiko ~ Mehrere Organe können betroffen sein.','-Ohne Kopfschmerz ist der Blutdruck normal ~ Das lässt sich nur messen.','-Eine einzelne Stressmessung beweist jede chronische Hypertonie ~ Wiederholte geeignete Messungen sind erforderlich.'),
 tq('Was verbessert die Aussagekraft einer Blutdruckmessung?','+Passende Manschettengröße ~ Eine falsche Größe verfälscht Werte.','+Ruhe und abgestützte Messposition ~ Standardisierte Bedingungen verbessern Vergleichbarkeit.','-Während der Messung intensiv sprechen ~ Das kann den Wert beeinflussen.','-Über dicker Kleidung messen ~ Das kann die Messung beeinträchtigen.'),
 tq('Bei sehr hohem Blutdruck treten neue Sprachstörung und Armschwäche auf. Was folgt?','+Sofortige Notfallbeurteilung ~ Akuter Organschaden ist möglich.','-Allein nach einer Stunde erneut messen ~ Die neurologischen Zeichen sind zeitkritisch.','-Zusätzliche Tabletten beliebiger Stärke geben ~ Unkontrollierte Senkung kann gefährlich sein.','-Beschwerden als Angst abtun ~ Organische Ursachen müssen abgeklärt werden.'),
 tq('Eine Person setzt Blutdruckmittel wegen Schwindel ab. Wie reagierst du?','+Symptome und Messwerte erfassen, ärztlich rückkoppeln ~ Die Therapie muss geprüft werden.','+Gemeinsam Einnahmeprobleme und Ziele besprechen ~ Beteiligung unterstützt sichere Adhärenz.','-Schwindel grundsätzlich ignorieren ~ Er kann Stürze begünstigen.','-Pauschal die doppelte Dosis empfehlen ~ Das kann die Beschwerden verschlimmern.')]);
disease('pad','Periphere arterielle Verschlusskrankheit','Herz und Gefäße','peripheral-arterial-disease-pad','Arterielle Durchblutungsstörung, häufig durch Atherosklerose der Beinarterien.','Belastungsschmerz mit Besserung in Ruhe|Kühle oder schlecht heilende Füße|Fortgeschritten: Ruheschmerz und Gewebeschaden','Haut, Wunden, Schmerzen und Durchblutung beurteilen|Passendes Gehtraining bei stabiler Erkrankung fachlich abstimmen|Fußschutz und Gefäßrisiken besprechen','Plötzlich sehr schmerzhaftes, kaltes oder taubes Bein kann eine akute Ischämie anzeigen.',[
 tq('Welche Beschwerde passt zur Claudicatio intermittens?','+Wadenschmerz beim Gehen mit Besserung in Ruhe ~ Belastung übersteigt die arterielle Versorgung.','-Immer beidseitig warme Knöchelödeme ~ Das ist kein typischer Leitsymptomkomplex.','-Ausschließlich juckende Augen ~ Das erklärt die Beinischämie nicht.','-Schmerzfreiheit schließt jede pAVK aus ~ Frühe Stadien können symptomarm sein.'),
 tq('Welche Beobachtungen sind bei pAVK wichtig?','+Wunden und Hauttemperatur ~ Sie geben Hinweise auf gefährdetes Gewebe.','+Neu auftretender Ruheschmerz ~ Das kann eine Verschlechterung anzeigen.','-Nur die Schwellung messen ~ Arterielle Durchblutung braucht weitere Beurteilung.','-Jede Blässe als normale Alterung werten ~ Eine Perfusionsstörung ist möglich.'),
 tq('Ein Bein wird plötzlich kalt, blass und stark schmerzhaft. Was folgt?','+Unverzügliche gefäßmedizinische Notfallabklärung ~ Akute Ischämie gefährdet das Bein.','-Kräftige Massage ~ Sie löst keinen arteriellen Verschluss.','-Ein mehrtägiger Gehversuch als erster Schritt ~ Das verzögert die Versorgung.','-Heiße Wärmflasche direkt auflegen ~ Bei Minderperfusion drohen unbemerkte Schäden.'),
 tq('Was ist vor Kompression bei einer Beinwunde zu klären?','+Arterielle Durchblutung und Kontraindikationen ~ Ausgeprägte Ischämie beeinflusst die Eignung.','-Jede Wunde braucht denselben hohen Kompressionsdruck ~ Die Ursache ist entscheidend.','-Ein venöses Aussehen ersetzt die Gefäßprüfung ~ Mischformen können vorkommen.','-Kompression darf ohne individuelle Beurteilung beginnen ~ Das kann bei Ischämie schaden.')]);
disease('dvt','Tiefe Venenthrombose','Herz und Gefäße','deep-vein-thrombosis-dvt','Blutgerinnsel in einer tiefen Vene, häufig im Bein.','Einseitige Schwellung und Schmerz|Überwärmung oder Farbveränderung möglich|Beschwerden können auch gering sein','Bei Verdacht zeitnah ärztliche Abklärung organisieren|Verordnete Antikoagulation und gegebenenfalls Kompression unterstützen|Mobilität nach medizinischer Beurteilung und Behandlungsplan fördern','Zusätzliche Atemnot oder Brustschmerz kann eine Lungenembolie bedeuten.',[
 tq('Welche Befunde passen zu einer tiefen Venenthrombose?','+Neu einseitig geschwollenes schmerzendes Bein ~ Das verlangt zeitnahe Abklärung.','+Überwärmung oder Verfärbung ~ Sie können begleitend auftreten.','-Fehlende Schmerzen schließen sie aus ~ Eine Thrombose kann symptomarm bleiben.','-Ein einzelner klinischer Handgriff beweist sie sicher ~ Apparative Diagnostik kann erforderlich sein.'),
 tq('Welche Faktoren fördern venöse Thrombosen?','+Immobilität ~ Sie begünstigt venöse Stase.','+Erhöhte Gerinnungsneigung ~ Sie ist Teil der Virchow-Trias.','-Regelmäßige Wadenmuskelaktivität als Regelursache ~ Bewegung unterstützt den venösen Rückstrom.','-Jede blaue Hautstelle ist eine tiefe Thrombose ~ Blutergüsse haben andere Ursachen.'),
 tq('Bei bekanntem Thromboseverdacht kommt plötzlich Atemnot hinzu. Was folgt?','+Sofortige Notfallbeurteilung wegen Embolieverdacht ~ Die Lungenstrombahn kann betroffen sein.','-Nur das Bein erneut vermessen ~ Das behandelt die akute Gefahr nicht.','-Das Bein kräftig ausstreichen ~ Das ist keine sichere Akuttherapie.','-Bis zum ambulanten Termin nächste Woche warten ~ Die Atemnot ist zeitkritisch.'),
 tq('Welche Aussage zur Versorgung nach gesicherter Thrombose ist richtig?','+Mobilisation richtet sich nach Behandlung und klinischem Zustand ~ Pauschale dauerhafte Bettruhe ist ungeeignet.','+Unter Antikoagulation Blutungszeichen beachten ~ Therapie braucht Sicherheitskontrollen.','-Alle müssen wochenlang strikt liegen ~ Das ist kein allgemeiner Standard.','-Kompression ersetzt jede Antikoagulationsprüfung ~ Die Maßnahmen haben unterschiedliche Ziele.')]);
disease('stroke','Schlaganfall','Neurologie','stroke','Akute Hirnschädigung durch Gefäßverschluss oder Blutung; die Unterscheidung erfordert Diagnostik.','Plötzliche Gesichts- oder Halbseitenlähmung|Sprach-, Seh- oder Gleichgewichtsstörung|Auch vorübergehende Ausfälle sind dringlich','Sofort Schlaganfallnotfall auslösen und letzten sicher symptomfreien Zeitpunkt klären|Vitalfunktionen und Blutzucker nach Standard beurteilen|Bis zur Schluckabklärung keine unkontrollierte orale Gabe','Eine rasche Rückbildung der Beschwerden ist keine Entwarnung: Eine TIA verlangt dringende Abklärung.',[
 tq('Welche neu aufgetretenen Befunde passen zu einem Schlaganfall?','+Hängender Mundwinkel und Armschwäche ~ Fokale Ausfälle sind typische Warnzeichen.','+Plötzliche Sprachstörung ~ Auch sie verlangt sofortige Abklärung.','-Nur vorhandener Brustschmerz erlaubt einen Verdacht ~ Neurologische Ausfälle sind eigenständig relevant.','-Symptomrückgang schließt eine Gefahr aus ~ Eine TIA kann vorausgehen.'),
 tq('Welche Information ist für die Akuttherapie besonders wichtig?','+Wann die Person zuletzt sicher symptomfrei war ~ Der Zeitverlauf beeinflusst Therapieentscheidungen.','-Nur der Zeitpunkt der nächsten Mahlzeit ~ Er ersetzt den Symptombeginn nicht.','-Ob Angehörige die Diagnose bereits benannt haben ~ Diagnostik erfolgt medizinisch.','-Ob die Lähmung schmerzhaft ist ~ Schmerz ist kein notwendiges Kriterium.'),
 tq('Nach neuem Schlaganfall verlangt eine Person Wasser. Eine Schluckprüfung fehlt. Was tust du?','+Orale Gabe zunächst zurückstellen und Schlucken abklären ~ Aspiration kann auch unauffällig erfolgen.','+Mundpflege und weitere Flüssigkeitsversorgung fachlich planen ~ Durst und Versorgung müssen berücksichtigt werden.','-Wasser immer mit Strohhalm geben ~ Das ist keine universelle Schluckstrategie.','-Medikamente ohne Rücksprache mörsern ~ Eignung und sicherer Weg sind zu klären.'),
 tq('Die halbseitige Schwäche verschwindet nach zehn Minuten. Welche Aussage ist richtig?','+Trotzdem sofortige ärztliche Notfallabklärung ~ Eine TIA erhöht das Schlaganfallrisiko.','-Die Person darf ungeprüft allein heimfahren ~ Wiederholung oder Verschlechterung ist möglich.','-Die Rückbildung beweist eine psychische Ursache ~ Das ist keine zulässige Schlussfolgerung.','-Erst nach mehreren Tagen Handlungsbedarf ~ Die Abklärung ist zeitkritisch.')]);
disease('parkinson','Parkinson-Erkrankung','Neurologie','parkinsons-disease','Fortschreitende neurologische Erkrankung mit Dopaminmangel; motorische und nichtmotorische Symptome.','Bradykinese, Rigor und häufig Ruhetremor|Freezing und Sturzgefährdung|Schluckprobleme und Kreislaufbeschwerden möglich','Medikamente zu individuell verordneten Zeiten geben|Bewegungsstrategien, sichere Transfers und genügend Zeit anbieten|Schluckauffälligkeiten und Wirkungsschwankungen weitergeben','Ein plötzlicher Funktionsverlust ist nicht automatisch normales Fortschreiten; Ursachen abklären.',[
 tq('Welche Symptome sind mit Parkinson vereinbar?','+Verlangsamte Bewegungen ~ Bradykinese ist ein zentrales motorisches Merkmal.','+Muskelsteifigkeit ~ Rigor ist ein typischer Befund.','-Tremor muss bei allen vorliegen ~ Nicht jede Person zeigt ausgeprägtes Zittern.','-Die Erkrankung betrifft nur das Gedächtnis ~ Motorik und weitere Funktionen sind betroffen.'),
 tq('Warum sind individuell festgelegte Einnahmezeiten wichtig?','+Verzögerungen können Wirkungsschwankungen verstärken ~ Beweglichkeit kann zeitabhängig schwanken.','-Alle Präparate wirken exakt gleich lang ~ Präparate unterscheiden sich.','-Parkinsonmittel dürfen bei Schluckproblemen abrupt entfallen ~ Die Gabe muss fachlich geklärt werden.','-Die Stationsroutine ersetzt die Verordnung ~ Entscheidend ist der individuelle Plan.'),
 tq('Vor einer Tür bleibt eine Person mit Freezing stehen. Welche Unterstützung passt?','+Ruhe, Zeit und vereinbarte Bewegungsreize anbieten ~ Gezielte Strategien können das Starten erleichtern.','+Sturzsicherheit und Hilfsmittelposition prüfen ~ Unterstützung muss sicher erfolgen.','-Ruckartig an beiden Armen ziehen ~ Das erhöht Verletzungs- und Sturzrisiko.','-Jede weitere Bewegung dauerhaft verbieten ~ Selbstständigkeit soll angemessen erhalten werden.'),
 tq('Beim Trinken hustet ein Parkinsonpatient wiederholt. Was folgt?','+Gabe unterbrechen und Schluckabklärung organisieren ~ Ein Aspirationsrisiko ist möglich.','-Mehr Flüssigkeit schnell nachreichen ~ Das kann die Gefahr verstärken.','-Dünnflüssiges ist grundsätzlich am sichersten ~ Konsistenz braucht individuelle Prüfung.','-Husten beweist eine gesicherte Pneumonie ~ Er ist zunächst ein Warnhinweis.')]);
disease('dementia','Demenz','Neurologie','dementia/about-dementia/what-is-dementia','Syndrom mit anhaltender kognitiver Beeinträchtigung und Auswirkungen auf den Alltag; verschiedene Ursachen.','Gedächtnis-, Sprach- oder Orientierungsprobleme|Zunehmende Schwierigkeiten im Alltag|Verhalten und Stimmung können sich verändern','Biografie, Gewohnheiten und erhaltene Fähigkeiten nutzen|Kurze verständliche Schritte und Orientierung anbieten|Schmerz, Bedürfnisse und akute Veränderungen gezielt beurteilen','Plötzliche Verschlechterung kann ein zusätzliches Delir sein und verlangt Ursachenabklärung.',[
 tq('Welche Aussagen zu Demenz treffen zu?','+Sie kann mehrere kognitive Funktionen betreffen ~ Mehr als Gedächtnis kann beeinträchtigt sein.','+Es gibt verschiedene Ursachen ~ Alzheimer ist eine häufige Demenzform.','-Sie ist ein unvermeidbarer Teil normalen Alterns ~ Demenz ist eine Erkrankung beziehungsweise ein Syndrom.','-Jede Vergesslichkeit beweist Demenz ~ Andere Ursachen müssen geprüft werden.'),
 tq('Was unterstützt ressourcenorientierte Pflege?','+Vertraute Tätigkeiten passend zur Fähigkeit ermöglichen ~ Erhaltene Kompetenzen werden genutzt.','+Kommunikation an das individuelle Verstehen anpassen ~ Überforderung kann reduziert werden.','-Alle Handlungen ungefragt übernehmen ~ Das kann Fähigkeiten und Selbstbestimmung schwächen.','-Fehler öffentlich korrigieren ~ Das kann beschämen und verunsichern.'),
 tq('Eine bisher mobile Bewohnerin mit Demenz ist seit heute auffällig schläfrig. Was folgt?','+Akute Ursachen und Delir prüfen lassen ~ Der plötzliche Wechsel ist erklärungsbedürftig.','-Als übliche Demenzentwicklung dokumentieren und abwarten ~ Demenz erklärt den akuten Beginn nicht sicher.','-Ohne Assessment ein Beruhigungsmittel verlangen ~ Ursachenorientierung hat Vorrang.','-Schmerz ausschließen, weil sie nichts sagt ~ Kommunikation kann Schmerzen verschleiern.'),
 tq('Welche Schmerzerfassung ist sinnvoll?','+Selbstauskunft ermöglichen, soweit möglich ~ Sie bleibt eine wichtige Informationsquelle.','+Bei eingeschränkter Auskunft Verhalten strukturiert beobachten ~ Beobachtungsinstrumente können ergänzen.','-BESD 0 beweist Schmerzfreiheit ~ Fehlende Zeichen schließen Schmerz nicht aus.','-Jede Unruhe ist sicher Schmerz ~ Auch andere Ursachen kommen infrage.')]);
disease('delir','Delir','Neurologie','sudden-confusion','Akut einsetzende, fluktuierende Störung insbesondere von Aufmerksamkeit und Bewusstsein; meist körperliche Auslöser.','Rasch veränderte Aufmerksamkeit und Orientierung|Schwankender Verlauf|Unruhe oder auffällige Verlangsamung','Akute Ursachen wie Infektion, Hypoxie oder Medikamente abklären lassen|Orientierung, Brille, Hörgerät und vertraute Begleitung ermöglichen|Geeignetes Screening und Verlaufskontrolle einsetzen','Ein hypoaktives Delir kann als Müdigkeit übersehen werden.',[
 tq('Welche Befunde sprechen eher für Delir als für langsam fortschreitende Demenz?','+Akuter Beginn innerhalb kurzer Zeit ~ Das ist charakteristisch für Delir.','+Im Tagesverlauf schwankende Aufmerksamkeit ~ Fluktuation ist ein wichtiger Hinweis.','-Seit Jahren gleichbleibende Vergesslichkeit allein ~ Das beschreibt keinen akuten Wechsel.','-Unruhe muss immer vorhanden sein ~ Auch hypoaktive Formen treten auf.'),
 tq('Welche Faktoren können ein Delir begünstigen?','+Infektion und Hypoxie ~ Körperliche Störungen können auslösend sein.','+Medikamentenänderungen und Dehydratation ~ Die Vorgeschichte muss geprüft werden.','-Eine vorhandene Demenz schützt davor ~ Sie kann die Anfälligkeit erhöhen.','-Nur psychiatrische Erkrankungen kommen als Ursache infrage ~ Häufig sind körperliche Ursachen relevant.'),
 tq('Eine postoperative Person ist neu desorientiert. Welche Maßnahmen passen?','+ABCDE und Ursachenabklärung nach Dringlichkeit ~ Behandelbare Auslöser müssen erkannt werden.','+Ruhige Orientierung und sensorische Hilfsmittel ~ Das unterstützt Wahrnehmung und Sicherheit.','-Sofort jede Person fixieren ~ Fixierung ist keine pauschale Delirbehandlung.','-Orientierung nur durch lautes Schimpfen herstellen ~ Das verstärkt Belastung.'),
 tq('Ein Patient ist still, schläfrig und kaum aufmerksam. Was ist richtig?','+Auch ein hypoaktives Delir erwägen ~ Delir kann ohne Unruhe verlaufen.','-Nur schreiende Personen haben ein Delir ~ Das ist fachlich falsch.','-Ein Screening ersetzt jede Ursachenabklärung ~ Es unterstützt, ersetzt aber keine Diagnostik.','-Ohne Fieber ist eine Infektion unmöglich ~ Fieber kann fehlen.')]);
disease('epilepsy','Epilepsie und Krampfanfall','Neurologie','epilepsy','Erkrankung mit Neigung zu epileptischen Anfällen; ein einzelner Anfall kann andere Ursachen haben.','Motorische Krämpfe möglich|Auch kurze Bewusstseins- oder Wahrnehmungsstörungen|Nach Anfällen oft Erholungsphase','Anfallsdauer messen, vor Verletzungen schützen, begleiten|Nichts in den Mund stecken und nicht gewaltsam festhalten|Nach dem Anfall Atmung und Bewusstsein prüfen; Notfallplan beachten','Ein Anfall ab fünf Minuten oder Serien ohne Erholung verlangt sofortige Notfallversorgung.',[
 tq('Welche Anfallsformen sind möglich?','+Generalisierte Krämpfe ~ Das ist eine mögliche Erscheinungsform.','+Kurzes Innehalten mit Bewusstseinsstörung ~ Nicht jeder Anfall ist motorisch auffällig.','-Jeder Anfall muss mit Sturz beginnen ~ Fokale Anfälle können anders verlaufen.','-Ein einzelner Anfall beweist immer Epilepsie ~ Die Ursache muss geklärt werden.'),
 tq('Was sollte während eines Krampfanfalls erfasst werden?','+Beginn, Dauer und beobachteter Ablauf ~ Das unterstützt Beurteilung und Therapie.','+Verletzungen und anschließende Erholung ~ Komplikationen müssen erkannt werden.','-Nur die Reaktion der Mitpatienten ~ Das ersetzt keine Anfallsbeobachtung.','-Eine exakte Diagnose durch Festhalten testen ~ Das ist keine diagnostische Methode.'),
 tq('Eine Person krampft. Welche Handlungen sind sicher?','+Gefährliche Gegenstände entfernen und Kopf schützen ~ Verletzungen sollen vermieden werden.','+Zeit messen und Hilfe nach Notfallplan ~ Die Dauer beeinflusst die Dringlichkeit.','-Einen Löffel zwischen die Zähne stecken ~ Das kann schwere Verletzungen verursachen.','-Arme und Beine gewaltsam fixieren ~ Das kann zu Verletzungen führen.'),
 tq('Der Krampfanfall dauert bereits fünf Minuten. Was folgt?','+Sofortige Notfalleskalation und Behandlung nach Plan ~ Ein prolongierter Anfall ist gefährlich.','-Weitere zwanzig Minuten ohne Hilfe warten ~ Das verzögert notwendige Behandlung.','-Orale Tabletten in den Mund legen ~ Schlucken ist nicht sicher.','-Nach Ende jede Atemkontrolle unterlassen ~ Atmung muss anschließend beurteilt werden.')]);
disease('ms','Multiple Sklerose','Neurologie','multiple-sclerosis','Chronische Erkrankung des zentralen Nervensystems mit entzündlicher Schädigung; Verläufe sind unterschiedlich.','Fatigue, Seh- oder Sensibilitätsstörungen|Spastik und unsicherer Gang|Blasenprobleme möglich','Aktivität mit Pausen und individuellen Zielen planen|Mobilität, Ausscheidung und Hautrisiken erfassen|Neue neurologische Veränderungen fachlich abklären lassen','Nicht jede Verschlechterung ist ein neuer Schub; Infekte und andere Ursachen prüfen.',[
 tq('Welche Beschwerden passen zu MS?','+Ausgeprägte Fatigue ~ Sie kann den Alltag stark beeinträchtigen.','+Seh- und Sensibilitätsstörungen ~ Das ZNS kann unterschiedlich betroffen sein.','-Immer ausschließlich Muskelschwäche der Beine ~ Die Symptome sind vielfältiger.','-Jeder Verlauf ist gleichförmig ~ Unterschiedliche Verlaufsformen sind möglich.'),
 tq('Welche Aussage zur Fatigue trifft zu?','+Sie kann trotz ausreichender Ruhe stark belasten ~ Sie ist mehr als gewöhnliche Müdigkeit.','-Sie beweist mangelnde Motivation ~ Das wertet ein Krankheitssymptom ab.','-Nur vollständige dauerhafte Bettruhe hilft ~ Aktivität muss passend dosiert werden.','-Sie ist an der Pulsfrequenz allein messbar ~ Auch Selbstauskunft und Alltag sind wichtig.'),
 tq('Eine Person mit MS möchte wieder einkaufen, ist aber rasch erschöpft. Was passt?','+Weg, Hilfsmittel und Pausen gemeinsam planen ~ Das verbindet Teilhabe und Belastungssteuerung.','+Erreichbare Ziele und Wirkung evaluieren ~ Planung braucht individuelle Rückmeldung.','-Das Ziel ohne Gespräch verbieten ~ Teilhabe und Autonomie bleiben wichtig.','-Nur maximale Belastung als Training gelten lassen ~ Überforderung ist kein geeignetes Ziel.'),
 tq('Bei MS verschlechtert sich der Gang zusammen mit Fieber. Was folgt?','+Infekt und weitere Ursachen abklären lassen ~ Nicht jede Verschlechterung ist ein Schub.','-Kortison eigenständig beginnen ~ Das erfordert ärztliche Entscheidung.','-Fieber ignorieren, weil MS bekannt ist ~ Eine behandelbare Ursache könnte vorliegen.','-Sicher einen neuen Schub diagnostizieren ~ Die Befunde allein reichen nicht aus.')]);
disease('t1d','Diabetes mellitus Typ 1','Stoffwechsel','type-1-diabetes','Meist autoimmune Zerstörung insulinbildender Betazellen mit absolutem Insulinmangel.','Durst und vermehrtes Wasserlassen|Gewichtsverlust und Müdigkeit|Bei Entgleisung Übelkeit und Bewusstseinsstörung','Insulin nach individuellem Plan und Glukosekontrollen unterstützen|Injektion, Kohlenhydrate und Hypoglykämieprävention schulen|Bei Krankheit vereinbarten Sick-Day-Plan und Ketonkontrollen beachten','Basalinsulin bei Nahrungskarenz nicht pauschal weglassen; ärztlich abgestimmter Plan ist erforderlich.',[
 tq('Was kennzeichnet Diabetes Typ 1?','+Ein absoluter Insulinmangel ~ Insulinbildende Zellen gehen meist autoimmun verloren.','-Ausschließlich eine Folge von Süßigkeiten ~ Das erklärt die autoimmune Erkrankung nicht.','-Insulin ist grundsätzlich unnötig ~ Es muss ersetzt werden.','-Nur ältere Erwachsene erkranken ~ Typ 1 kann in verschiedenen Altersgruppen auftreten.'),
 tq('Welche Symptome können zur Erstmanifestation passen?','+Starker Durst und häufiges Wasserlassen ~ Glukosebedingte Wasserverluste sind möglich.','+Unbeabsichtigter Gewichtsverlust ~ Energiemangel kann Gewicht reduzieren.','-Jede Gewichtszunahme beweist Typ 1 ~ Die Diagnose erfordert Laborbeurteilung.','-Normale Wachheit schließt Diabetes aus ~ Frühe Stadien können wenig auffallen.'),
 tq('Eine Person mit Typ 1 erbricht und isst nicht. Welche Aussage ist richtig?','+Insulinbedarf und Kontrollen nach Krankheitsplan klären ~ Ohne Insulin droht Ketoazidose.','+Bei Entgleisungszeichen dringend Hilfe organisieren ~ Erbrechen kann ein Warnzeichen sein.','-Alle Insuline grundsätzlich auslassen ~ Auch ohne Mahlzeit besteht Grundbedarf.','-Keine Glukosemessung nötig, da nichts gegessen wird ~ Krankheit kann Werte erhöhen.'),
 tq('Welche Schulungsinhalte fördern sichere Selbstversorgung?','+Hypoglykämiezeichen und Handlungsplan ~ Frühzeitiges Handeln verhindert Verschlechterung.','+Injektionstechnik praktisch überprüfen ~ Durchführung beeinflusst die Wirkung.','-Dosen anderer Personen übernehmen ~ Insulintherapie ist individuell.','-Blutzuckerwerte unabhängig von Einheiten vergleichen ~ mg/dl und mmol/l sind verschieden.')]);
disease('t2d','Diabetes mellitus Typ 2','Stoffwechsel','type-2-diabetes','Insulin wirkt vermindert; im Verlauf kann die Insulinproduktion unzureichend werden.','Lange symptomarm möglich|Durst, Müdigkeit und häufiges Wasserlassen|Spätfolgen an Gefäßen, Nerven, Augen und Nieren','Individuelle Therapie und alltagstaugliche Ziele begleiten|Füße und Haut beobachten, geeignete Fußversorgung fördern|Kontrollen und Medikamentensicherheit besprechen','Auch Menschen mit Typ 2 können Hypoglykämien oder schwere hyperglykämische Entgleisungen entwickeln.',[
 tq('Welche Aussagen zu Typ-2-Diabetes sind richtig?','+Insulinresistenz ist ein wesentlicher Mechanismus ~ Zellen reagieren vermindert auf Insulin.','+Im Verlauf kann Insulin nötig werden ~ Die Eigenproduktion kann nachlassen.','-Alle Betroffenen benötigen sofort dieselbe Insulindosis ~ Therapie und Bedarf unterscheiden sich.','-Normalgewicht schließt die Erkrankung aus ~ Gewicht ist kein sicheres Ausschlusskriterium.'),
 tq('Warum ist die Fußbeobachtung wichtig?','+Neuropathie kann Verletzungen unbemerkt lassen ~ Die Schmerzempfindung kann vermindert sein.','+Durchblutungsstörungen können Heilung beeinträchtigen ~ Kleine Wunden können problematisch werden.','-Schmerzfreiheit beweist einen gesunden Fuß ~ Neuropathie kann Schmerz verdecken.','-Hornhaut darf immer selbst tief entfernt werden ~ Verletzungen sollen fachgerecht vermieden werden.'),
 tq('Eine Person mit Diabetes bemerkt eine neue Fußwunde, hat aber keinen Schmerz. Was folgt?','+Zeitnahe fachliche Wund- und Durchblutungsbeurteilung ~ Schmerzfreiheit ist keine Entwarnung.','-Weiterlaufen, bis Schmerzen auftreten ~ Eine Neuropathie kann Warnsignale verhindern.','-Heiße Fußbäder als sichere Standardtherapie ~ Temperatur- und Hautschäden sind möglich.','-Nur mit einer Socke abdecken und nicht melden ~ Fachliche Beurteilung ist erforderlich.'),
 tq('Was unterstützt eine wirksame Beratung?','+Ziele gemeinsam an Alltag und Möglichkeiten anpassen ~ Beteiligung fördert Umsetzbarkeit.','+Hypoglykämierisiko der konkreten Therapie klären ~ Nicht alle Medikamente haben dasselbe Risiko.','-Diabetes als persönliches Versagen darstellen ~ Das behindert die Zusammenarbeit.','-Jedem jede Kohlenhydratzufuhr verbieten ~ Ernährung wird individuell geplant.')]);
disease('hypo','Hypoglykämie','Stoffwechsel','low-blood-sugar-hypoglycaemia','Zu niedrige Glukose; bei Diabetes ist unter 70 mg/dl beziehungsweise 3,9 mmol/l eine Warnschwelle.','Zittern, Schwitzen und Heißhunger|Verwirrtheit und Sprachstörung möglich|Schwer: Krampfanfall oder Bewusstlosigkeit','Glukose, Bewusstsein und Schluckfähigkeit prüfen|Bei sicherem Schlucken rasch wirksame Kohlenhydrate nach Plan und Kontrolle|Bei unsicherem Schlucken keine orale Gabe, Notfallversorgung','Schwere Hypoglykämie wird durch notwendigen Fremdhilfebedarf charakterisiert; nicht nur durch einen Zahlenwert.',[
 tq('Welche Symptome können eine Hypoglykämie anzeigen?','+Kaltschweißigkeit und Zittern ~ Das sind mögliche autonome Warnzeichen.','+Neue Verwirrtheit ~ Glukosemangel kann das Gehirn beeinträchtigen.','-Nur Durst beweist eine Unterzuckerung ~ Die Glukose muss beurteilt werden.','-Fehlender Heißhunger schließt sie aus ~ Warnzeichen können vermindert sein.'),
 tq('Welche Einheit gehört korrekt zur Warnschwelle?','+70 mg/dl entspricht ungefähr 3,9 mmol/l ~ Beide Angaben beschreiben dieselbe Größenordnung.','-70 mmol/l ist die übliche Hypoglykämieschwelle ~ Das wäre eine extrem hohe Glukose.','-3,9 mg/dl ist dasselbe wie 70 mg/dl ~ Die Einheiten sind nicht austauschbar.','-Jede Unterzuckerung hat denselben Schweregrad ~ Symptome und Hilfebedarf unterscheiden sich.'),
 tq('Eine unterzuckerte Person ist wach und schluckt sicher. Was passt?','+Rasch wirksame Kohlenhydrate nach individuellem Plan ~ Sie sollen die Glukose zügig anheben.','+Zeitnahe erneute Messung und weitere Beobachtung ~ Wiederabsinken ist möglich.','-Zusätzlich Insulin zur Korrektur geben ~ Das würde die Glukose weiter senken.','-Nur fettreiche Schokolade als erste Wahl ~ Fett verzögert die rasche Zuckeraufnahme.'),
 tq('Eine bewusstlose Person mit Hypoglykämie atmet normal. Was ist angemessen?','+Notfallhilfe, Atemwegssicherung und stabile Seitenlage ~ Bewusstsein und Atmung bleiben zu überwachen.','+Glukagon nach gültigem Notfallplan und Qualifikation ~ Eine nichtorale Behandlung kann vorgesehen sein.','-Saft in den Mund gießen ~ Es besteht Aspirationsgefahr.','-Bei fehlender normaler Atmung nur Seitenlage ~ Dann ist Reanimation erforderlich.')]);
disease('dka','Diabetische Ketoazidose','Stoffwechsel','diabetic-ketoacidosis','Akute Stoffwechselentgleisung durch Insulinmangel mit Ketonkörperbildung und Azidose.','Durst, Polyurie und Flüssigkeitsverlust|Bauchschmerz und Erbrechen|Tiefe Atmung, fruchtiger Atem und Bewusstseinsstörung möglich','Bei Verdacht sofort medizinisch eskalieren|Glukose und Ketone nach Standard kontrollieren|Flüssigkeit, Insulin und Elektrolyte ärztlich gesteuert überwachen','Auch bei nicht stark erhöhter Glukose ist eine Ketoazidose möglich, etwa unter SGLT2-Hemmern.',[
 tq('Welche Befunde passen zu einer Ketoazidose?','+Erbrechen und tiefe Atmung bei Diabetes ~ Eine metabolische Entgleisung ist möglich.','+Erhöhte Ketone ~ Sie unterstützen den Verdacht.','-Nur ein hoher Glukosewert beweist jede Ketoazidose ~ Ketone und Säure-Basen-Status sind relevant.','-Fehlender Azetongeruch schließt sie aus ~ Dieses Zeichen muss nicht vorliegen.'),
 tq('Welcher Mechanismus ist zentral?','+Insulinmangel mit vermehrter Ketonkörperbildung ~ Dadurch kann eine Azidose entstehen.','-Ein reiner Sauerstoffüberschuss ~ Das erklärt den Mechanismus nicht.','-Grundsätzlich zu viel wirksames Insulin ~ Das führt eher zur Hypoglykämie.','-Ausschließlich eine Nahrungsmittelallergie ~ Das ist eine andere Pathophysiologie.'),
 tq('Ein Jugendlicher mit Typ 1 erbricht, atmet tief und wird schläfrig. Was folgt?','+Sofortige Notfallbeurteilung ~ DKA kann lebensbedrohlich sein.','+Glukose und Ketone erheben, ohne Alarmierung zu verzögern ~ Werte unterstützen die Versorgung.','-Nur abwarten, bis er wieder essen kann ~ Die Entgleisung kann fortschreiten.','-Ein frei geschätzter großer Insulinbolus ~ Therapie braucht kontrollierte Steuerung.'),
 tq('Warum werden Elektrolyte während der DKA-Behandlung eng kontrolliert?','+Flüssigkeits- und Insulintherapie verändern Elektrolyte ~ Insbesondere Kaliumverschiebungen können gefährlich sein.','-Ein normaler erster Kaliumwert beendet alle Kontrollen ~ Der Verlauf kann sich ändern.','-Elektrolyte haben keinen Bezug zum Herzrhythmus ~ Störungen können Arrhythmien auslösen.','-Nur der Blutzucker bestimmt die gesamte Therapie ~ Azidose und Kreislauf sind ebenfalls relevant.')]);
disease('hyperthy','Hyperthyreose','Stoffwechsel','overactive-thyroid-hyperthyroidism','Übermäßige Wirkung beziehungsweise Produktion von Schilddrüsenhormonen.','Herzrasen und Wärmeintoleranz|Zittern und Unruhe|Gewichtsverlust möglich','Puls, Gewicht, Temperatur und Belastbarkeit verfolgen|Verordnete Therapie und Nebenwirkungen beobachten|Ausgeprägte Verschlechterung dringlich abklären','Hohes Fieber, starke Tachykardie und Bewusstseinsänderung können eine thyreotoxische Krise anzeigen.',[
 tq('Welche Kombination passt zu Hyperthyreose?','+Wärmeintoleranz und Herzrasen ~ Ein gesteigerter Stoffwechsel ist möglich.','+Gewichtsverlust und Tremor ~ Beides kann vorkommen.','-Kälteintoleranz ist das einzige Leitsymptom ~ Das passt eher zur Unterfunktion.','-Bradykardie muss immer bestehen ~ Häufig besteht eher Tachykardie.'),
 tq('Welche Information ist für die Verlaufskontrolle nützlich?','+Puls, Gewicht und subjektive Beschwerden ~ Gemeinsam bilden sie Veränderungen ab.','-Nur die Anzahl der Mahlzeiten ~ Sie bewertet die Hormonlage nicht ausreichend.','-Ein einzelner normaler Puls beweist Heilung ~ Labor und Verlauf bleiben relevant.','-Beschwerdefreiheit erlaubt immer eigenständiges Absetzen ~ Änderungen sind abzustimmen.'),
 tq('Bei bekannter Hyperthyreose treten hohes Fieber, starke Tachykardie und Verwirrtheit auf. Was folgt?','+Sofortige Notfalleskalation ~ Eine schwere Krise muss ausgeschlossen werden.','-Nur ein kühles Getränk und Abwarten ~ Das reicht bei dieser Konstellation nicht.','-Als übliche Nervosität bewerten ~ Bewusstseinsveränderung ist ein Warnsignal.','-Zusätzliche Schilddrüsenhormone geben ~ Das könnte die Überfunktion verstärken.'),
 tq('Was ist bei Beratung sinnvoll?','+Medikation und Rückmeldezeichen gemeinsam besprechen ~ Selbstbeobachtung unterstützt sichere Therapie.','+Neue Herzbeschwerden zeitnah melden ~ Rhythmusstörungen können auftreten.','-Alle Symptome ausschließlich psychisch erklären ~ Körperliche Ursachen sind relevant.','-Jede Dosisänderung allein nach Gewicht vornehmen ~ Labor und ärztliche Beurteilung sind erforderlich.')]);
disease('hypothy','Hypothyreose','Stoffwechsel','underactive-thyroid-hypothyroidism','Unzureichende Versorgung mit Schilddrüsenhormonen.','Müdigkeit und Kälteempfindlichkeit|Gewichtszunahme und Obstipation|Verlangsamung und trockene Haut','Alltagsfunktion, Ausscheidung und Beschwerden erfassen|Hormonersatz nach konkreter Verordnung und Einnahmehinweisen unterstützen|Laborkontrollen und Wechselwirkungen beachten','Ausgeprägte Bewusstseinsstörung mit Unterkühlung ist ein Notfall; nicht als gewöhnliche Müdigkeit abtun.',[
 tq('Welche Symptome passen zur Hypothyreose?','+Kälteempfindlichkeit und Verlangsamung ~ Der Stoffwechsel ist häufig vermindert.','+Obstipation und trockene Haut ~ Diese Beschwerden können auftreten.','-Gewichtsverlust mit starkem Schwitzen als typisches Gesamtbild ~ Das passt eher zur Überfunktion.','-Jede Müdigkeit beweist eine Unterfunktion ~ Es bestehen viele mögliche Ursachen.'),
 tq('Wie wird der Verdacht weiter abgeklärt?','+Ärztliche Beurteilung mit Schilddrüsenlabor ~ Symptome allein reichen nicht zur Diagnose.','-Nur durch einmaliges Pulstasten ~ Das ersetzt das Labor nicht.','-Durch eine selbst gewählte Probemedikation ~ Das birgt Risiken.','-Ausschließlich durch Beobachtung der Haarfarbe ~ Das ist kein Diagnosekriterium.'),
 tq('Eine Person nimmt Levothyroxin unregelmäßig und zusätzlich Eisenpräparate. Was klärst du?','+Verordnung und präparatspezifische Einnahmeabstände ~ Wechselwirkungen können die Aufnahme verändern.','+Gründe für unregelmäßige Einnahme ~ Eine alltagstaugliche Lösung ist nötig.','-Alle Mittel ohne Prüfung gleichzeitig geben ~ Die Aufnahme kann beeinträchtigt werden.','-Dosis nach Gefühl täglich neu bestimmen ~ Anpassungen brauchen fachliche Kontrolle.'),
 tq('Eine stark unterkühlte Person mit Hypothyreose wird kaum ansprechbar. Was folgt?','+Unverzügliche strukturierte Notfallbeurteilung ~ Eine schwere Entgleisung ist möglich.','-Als normale Folge schlechten Schlafs einordnen ~ Die Konstellation ist gefährlich.','-Nur zur Bewegung auffordern ~ Eine Akutbeurteilung hat Vorrang.','-Ohne Hilfe bis zum nächsten Labortermin warten ~ Die Bewusstseinsstörung ist zeitkritisch.')]);
disease('aki','Akute Nierenschädigung','Niere und Harnwege','acute-kidney-injury','Plötzliche Verschlechterung der Nierenfunktion; Ursachen können vor, in oder nach der Niere liegen.','Verminderte Urinmenge möglich|Übelkeit, Ödeme oder Atemnot|Auch ohne auffällige Symptome möglich','Urinmenge, Flüssigkeitsbilanz, Kreislauf und Laborverlauf erfassen|Medikamente und mögliche Abflussstörung prüfen lassen|Flüssigkeit nach Ursache und Anordnung, keine pauschale Überwässerung','Oligurie mit Kreislaufstörung oder Atemnot erfordert dringende Beurteilung.',[
 tq('Welche Ursachen können eine akute Nierenschädigung auslösen?','+Flüssigkeitsmangel und niedriger Blutdruck ~ Die Nierendurchblutung kann sinken.','+Harnabflussbehinderung ~ Eine postrenale Ursache ist möglich.','-Normale Urinmenge schließt sie aus ~ Auch nichtoligurische Verläufe kommen vor.','-Nur chronischer Diabetes ist eine mögliche Ursache ~ Akute Auslöser sind vielfältig.'),
 tq('Welche Beobachtung ist besonders relevant?','+Zeitbezogene Urinmenge und Verlauf ~ Einzelne Mengen ohne Zeitraum sind wenig aussagekräftig.','+Gewicht, Bilanz und Kreislauf ~ Sie unterstützen die Volumenbeurteilung.','-Nur die Farbe eines Urinbeutels ~ Das reicht zur Funktionsbeurteilung nicht.','-Ausschließlich das Durstgefühl ~ Es kann unzuverlässig sein.'),
 tq('Eine ältere Person hat Durchfall, wenig Urin und nimmt Ibuprofen. Was folgt?','+Zeitnahe Beurteilung von Kreislauf, Hydratation und Nierenfunktion ~ Volumenmangel und NSAR sind relevant.','+Medikamenteneinnahme vollständig weitergeben ~ Sie beeinflusst die Behandlung.','-Zusätzlich Ibuprofen empfehlen ~ Das kann die Nieren weiter belasten.','-Viel Flüssigkeit unabhängig von Herzfunktion aufzwingen ~ Die Menge muss individuell sein.'),
 tq('Bei geringer Urinmenge über einen Katheter: Was ist sinnvoll?','+Schlauchverlauf und Abfluss prüfen ~ Ein mechanisches Problem ist möglich.','+Gleichzeitig klinischen Zustand beurteilen ~ Eine Abflussprüfung ersetzt kein Assessment.','-Den Befund grundsätzlich als Nierenversagen diagnostizieren ~ Mehrere Ursachen kommen infrage.','-Ohne Anordnung beliebig spülen ~ Das kann Risiken bergen.')]);
disease('ckd','Chronische Nierenkrankheit','Niere und Harnwege','kidney-disease','Anhaltende Nierenschädigung oder Funktionseinschränkung; Verlauf und Stadium bestimmen die Versorgung.','Früh oft symptomarm|Später Müdigkeit, Ödeme und Juckreiz möglich|Blutdruck-, Elektrolyt- und Flüssigkeitsprobleme','Nierenfunktion, Bilanz, Gewicht und verordnete Kontrollen beachten|Medikamente auf nötige Anpassung prüfen lassen|Ernährung und Trinkmenge individuell mit Fachteam planen','Atemnot, neue Verwirrtheit oder stark veränderte Ausscheidung können dringlich sein.',[
 tq('Welche Aussage zur chronischen Nierenkrankheit trifft zu?','+Früh kann sie ohne Beschwerden verlaufen ~ Labor und Urinbefunde können sie aufdecken.','-Jede betroffene Person braucht sofort Dialyse ~ Stadium und Verlauf unterscheiden sich.','-Normales Wasserlassen beweist normale Filtration ~ Urinmenge und Funktion sind verschieden.','-Sie heilt grundsätzlich innerhalb eines Tages ~ Sie ist eine chronische Erkrankung.'),
 tq('Warum ist eine Arzneimittelprüfung wichtig?','+Einige Wirkstoffe oder Metaboliten werden renal ausgeschieden ~ Bei eingeschränkter Funktion droht Akkumulation.','+NSAR können zusätzliche Risiken bringen ~ Die Eignung muss geprüft werden.','-Alle Medikamente müssen immer halbiert werden ~ Anpassungen sind präparat- und situationsabhängig.','-Rezeptfreie Mittel sind stets unbedenklich ~ Auch sie können relevant sein.'),
 tq('Eine Person mit CKD fragt nach Trinkmenge und Kaliumverbot. Was antwortest du fachlich?','+Die Vorgaben hängen von Funktion, Labor und Behandlung ab ~ Pauschale Regeln sind ungeeignet.','+Ernährungsberatung und Behandlungsteam einbeziehen ~ Empfehlungen müssen alltagstauglich und passend sein.','-Alle müssen gleich viel zusätzlich trinken ~ Überwässerung kann gefährlich sein.','-Kaliumreiche Nahrung ist für alle grundsätzlich verboten ~ Maßgeblich ist die individuelle Situation.'),
 tq('Bei fortgeschrittener CKD treten Atemnot und zunehmende Ödeme auf. Was folgt?','+Zeitnahe klinische Beurteilung und Eskalation nach Schwere ~ Eine Überwässerung ist möglich.','-Nur die Beine beobachten ~ Atmung und Kreislauf sind wesentlich.','-Diuretikadosis ohne Plan verdoppeln ~ Änderungen benötigen fachliche Abstimmung.','-Die Bilanz reicht als alleinige Diagnose ~ Die Gesamtsituation muss beurteilt werden.')]);
disease('uti','Harnwegsinfektion','Niere und Harnwege','urinary-tract-infections-utis','Infektion der Harnwege; eine Beteiligung der Nieren kann schwerer verlaufen.','Brennen und häufiger Harndrang|Unterbauchschmerz möglich|Fieber und Flankenschmerz sprechen für mögliche obere Beteiligung','Beschwerden, Vitalwerte und Risikofaktoren erfassen|Urinprobe sachgerecht nach Anordnung gewinnen|Therapie und geeignete Flüssigkeitsversorgung unterstützen','Geruch oder positiver Teststreifen allein beweisen keine behandlungsbedürftige Infektion.',[
 tq('Welche Symptome passen zu einer Harnwegsinfektion?','+Brennen beim Wasserlassen und Harndrang ~ Das passt zu unteren Harnwegsbeschwerden.','+Fieber mit Flankenschmerz ~ Eine Nierenbeteiligung ist möglich.','-Nur dunkler Urin beweist eine Infektion ~ Auch Flüssigkeitsmangel kommt infrage.','-Jede Bakteriurie verlangt automatisch Antibiotika ~ Symptome und Situation sind entscheidend.'),
 tq('Was ist bei der Urinprobe wichtig?','+Geeignete Entnahme und zeitnahe Weitergabe ~ Verunreinigung kann Ergebnisse verfälschen.','-Eine Probe aus einem alten Sammelbeutel ist immer gleichwertig ~ Lagerung und Kontamination beeinflussen sie.','-Das Röhrchen ohne Zuordnung versenden ~ Eine eindeutige Identifikation ist erforderlich.','-Eine Probe ersetzt die klinische Beurteilung ~ Beschwerden und Kontext bleiben wichtig.'),
 tq('Eine Bewohnerin ist neu verwirrt; Urin riecht stark. Was folgt?','+Gesamte Akutsituation und mögliche Ursachen beurteilen ~ Verwirrtheit hat viele Ursachen.','+Vitalzeichen und passende Diagnostik abstimmen ~ Ein Infekt ist eine Möglichkeit.','-Ohne weitere Prüfung sicher HWI diagnostizieren ~ Geruch allein genügt nicht.','-Jede andere Ursache ausschließen ~ Medikamente, Hypoxie oder Stoffwechsel sind ebenfalls relevant.'),
 tq('Bei vermuteter HWI treten Schüttelfrost, niedriger Blutdruck und Verwirrtheit auf. Was tust du?','+Sofortige Notfalleskalation wegen möglicher Sepsis ~ Systemische Verschlechterung ist gefährlich.','-Nur Wärmflasche und Ruhe anbieten ~ Das reicht nicht zur Akutversorgung.','-Den Urintest am Folgetag abwarten ~ Die Versorgung darf nicht verzögert werden.','-Zuerst allein zur Toilette schicken ~ Kreislaufinstabilität erhöht das Risiko.')]);
disease('gastro','Akute Gastroenteritis','Verdauung','diarrhoea-and-vomiting','Akute Magen-Darm-Erkrankung, häufig infektiös, mit Durchfall und/oder Erbrechen.','Wässrige Stühle, Übelkeit und Erbrechen|Bauchkrämpfe|Bei Verlusten Dehydratationszeichen','Aufnahme, Verluste, Gewicht und Kreislauf beobachten|Geeignete orale Rehydratation bei sicherem Trinken unterstützen|Hygiene und erregerspezifische Schutzmaßnahmen beachten','Wenig Urin, Kreislaufstörung, Blut im Stuhl oder ausgeprägte Teilnahmslosigkeit verlangen Abklärung.',[
 tq('Welche Komplikation ist besonders zu beachten?','+Dehydratation und Elektrolytverlust ~ Durchfall und Erbrechen führen zu Verlusten.','-Jede Diarrhö verursacht sofort Darmverschluss ~ Das ist keine allgemeine Folge.','-Nur Durst zeigt Flüssigkeitsmangel zuverlässig ~ Auch Urin und Kreislauf sind wichtig.','-Klares Bewusstsein schließt relevante Verluste aus ~ Früh können Betroffene noch wach sein.'),
 tq('Was gehört zur Beobachtung?','+Häufigkeit und Beschaffenheit von Stuhl und Erbrechen ~ Das beschreibt Art und Umfang der Verluste.','+Trinkmenge, Urin und Kreislauf ~ Das unterstützt die Hydratationsbeurteilung.','-Nur die Zahl der Toilettengänge ohne Kontext ~ Menge und Zustand fehlen dann.','-Auf Dokumentation aller Verluste verzichten ~ Der Verlauf wird sonst unklar.'),
 tq('Ein älterer Patient mit Durchfall ist schwindelig und uriniert kaum. Was folgt?','+Zeitnahe Beurteilung von Kreislauf, Bilanz und Labor ~ Schwere Verluste und AKI sind möglich.','-Nur antidiarrhoische Mittel frei auswählen ~ Ursache und Risiken müssen geklärt werden.','-Trinken grundsätzlich verbieten ~ Eine passende Rehydratation ist erforderlich.','-Nur auf die nächste Mahlzeit warten ~ Die aktuellen Zeichen sind relevant.'),
 tq('Mehrere Personen einer Station entwickeln Erbrechen. Welche Schritte passen?','+Hygieneteam und zuständige Stelle nach Standard informieren ~ Ein Ausbruch muss früh erkannt werden.','+Erregerspezifische Maßnahmen und geeignete Händehygiene ~ Schutzmaßnahmen hängen vom Erreger ab.','-Handschuhe ersetzen jede Händehygiene ~ Auch Handschuhe können Keime übertragen; die Händehygiene bleibt indikationsgerecht nötig.','-Alle gemeinsam betreuen ohne Schutzprüfung ~ Übertragungen könnten zunehmen.')]);
disease('crohn','Morbus Crohn','Verdauung','crohns-disease','Chronisch entzündliche Darmerkrankung; unterschiedliche Abschnitte des Verdauungstrakts können betroffen sein.','Bauchschmerz und wiederkehrende Diarrhö|Gewichtsverlust und Fatigue|Fisteln oder perianale Beschwerden möglich','Stuhl, Schmerz, Ernährung und Gewicht erfassen|Therapie, Hautschutz und passende Ernährung begleiten|Psychische Belastung und Alltagsteilhabe besprechen','Starke neue Schmerzen, Fieber oder Kreislaufstörung verlangen dringende Abklärung.',[
 tq('Welche Aussagen zu Morbus Crohn treffen zu?','+Verschiedene Abschnitte des Verdauungstrakts können betroffen sein ~ Der Befall ist nicht auf den Dickdarm begrenzt.','+Schubweise Beschwerden sind möglich ~ Aktivität und Ruhephasen können wechseln.','-Immer nur das Rektum ist betroffen ~ Das ist keine passende Begrenzung.','-Die Erkrankung ist grundsätzlich ansteckend ~ Sie ist keine gewöhnliche Infektionsdiarrhö.'),
 tq('Welche Probleme sollten im Assessment erfragt werden?','+Stuhlveränderung, Schmerz und Gewichtsverlauf ~ Sie zeigen Krankheits- und Ernährungsbelastung.','+Auswirkungen auf Schule, Beruf und Beziehungen ~ Chronische Krankheit betrifft den Alltag.','-Nur die Medikamentenanzahl ~ Das erfasst den Pflegebedarf nicht vollständig.','-Beschwerdefreiheit macht jede Kontrolle unnötig ~ Verlaufskontrollen bleiben relevant.'),
 tq('Ein Patient mit Crohn verliert Gewicht und meidet Essen aus Angst vor Beschwerden. Was passt?','+Ernährungsstatus und konkrete Auslöser erfassen ~ Eine bedarfsgerechte Unterstützung ist nötig.','+Ernährungsberatung und Behandlungsteam einbeziehen ~ Es gibt keine passende Einheitsdiät.','-Dauerhafte Nahrungskarenz ohne Plan empfehlen ~ Das kann Mangelernährung verstärken.','-Alle Ballaststoffe lebenslang verbieten ~ Empfehlungen hängen von Situation und Verträglichkeit ab.'),
 tq('Bei CED treten starke neue Bauchschmerzen und Fieber auf. Was folgt?','+Dringende medizinische Beurteilung ~ Komplikationen oder Infekte sind möglich.','-Als sicheren gewöhnlichen Schub ohne Prüfung bewerten ~ Andere Ursachen müssen berücksichtigt werden.','-Immunsuppression selbstständig erhöhen ~ Das erfordert ärztliche Entscheidung.','-Nur die nächste Routinekontrolle abwarten ~ Akute Warnzeichen brauchen frühere Abklärung.')]);
disease('colitis','Colitis ulcerosa','Verdauung','ulcerative-colitis','Chronisch entzündliche Erkrankung von Dickdarm und Rektum.','Häufig blutig-schleimige Diarrhö|Stuhldrang und Bauchschmerz|Fatigue und Gewichtsverlust möglich','Stuhlfrequenz, Blutbeimengung und Kreislauf verfolgen|Flüssigkeit, Ernährung und Hautschutz individuell planen|Therapieadhärenz und psychosoziale Belastung besprechen','Häufige Blutstühle, Fieber, geblähter schmerzhafter Bauch oder Kreislaufstörung sind Warnzeichen.',[
 tq('Welcher Befund passt besonders zu Colitis ulcerosa?','+Blutig-schleimige Durchfälle ~ Dickdarm und Rektum sind entzündet.','-Immer nur Dünndarmbefall ~ Das passt nicht zur typischen Lokalisation.','-Blut im Stuhl ist immer harmlos ~ Es muss eingeordnet werden.','-Die Erkrankung verursacht nie Stuhldrang ~ Drang kann stark belasten.'),
 tq('Was unterscheidet sie typischerweise von Morbus Crohn?','+Die Entzündung betrifft Dickdarm und Rektum ~ Crohn kann weitere Abschnitte betreffen.','-Beide sind definitionsgemäß ausschließlich infektiös ~ Es handelt sich um CED.','-Nur Crohn kann den Alltag belasten ~ Beide können erheblich beeinträchtigen.','-Colitis braucht grundsätzlich keine Verlaufskontrollen ~ Auch hier ist Kontrolle wichtig.'),
 tq('Eine Person berichtet zwölf blutige Stühle, Schwindel und starke Schwäche. Was folgt?','+Dringende Beurteilung von Kreislauf, Blutverlust und Hydratation ~ Ein schwerer Verlauf ist möglich.','+Verluste und Vitalwerte strukturiert weitergeben ~ Das unterstützt die Versorgung.','-Nur ein anderes Toilettenpapier empfehlen ~ Die systemische Gefahr bleibt unbehandelt.','-Ohne Prüfung stuhlhemmende Medikamente geben ~ Bei schwerer Kolitis können Risiken bestehen.'),
 tq('Welche Unterstützung fördert den Alltag?','+Diskrete erreichbare Toiletten und Pausen planen ~ Drang und Scham werden berücksichtigt.','+Ernährung und Aktivität nach Situation abstimmen ~ Die Bedürfnisse sind individuell.','-Blutstühle vor dem Team geheim halten ~ Klinisch relevante Angaben müssen weitergegeben werden.','-Betroffene für häufige Toilettengänge tadeln ~ Das ist unprofessionell und belastend.')]);
disease('cirrhosis','Leberzirrhose','Verdauung','cirrhosis','Fortgeschrittener narbiger Umbau der Leber mit Funktionsverlust und möglichem Pfortaderhochdruck.','Aszites und Ödeme|Gelbsucht und Blutungsneigung|Verwirrtheit bei Enzephalopathie möglich','Gewicht, Bauchumfang und Flüssigkeit im Verlauf beurteilen|Ernährung, Haut und verordnete Therapie unterstützen|Bewusstseinsveränderung und Blutungen sofort weitergeben','Bluterbrechen, Teerstuhl oder neue Verwirrtheit sind dringliche Warnzeichen.',[
 tq('Welche Befunde passen zu einer dekompensierten Leberzirrhose?','+Aszites ~ Flüssigkeit kann sich im Bauch ansammeln.','+Ikterus und Blutungsneigung ~ Leberfunktion und Gerinnung können beeinträchtigt sein.','-Ein unauffälliger Bauch schließt jede Zirrhose aus ~ Früh kann sie symptomarm sein.','-Nur Alkohol kann eine Zirrhose verursachen ~ Es gibt weitere Ursachen.'),
 tq('Welche Verlaufskontrollen unterstützen die Pflege?','+Gewicht und Bauchumfang vergleichbar erfassen ~ Das hilft, Flüssigkeitsveränderungen zu erkennen.','+Bewusstsein und Blutungszeichen beobachten ~ Komplikationen können früh auffallen.','-Nur die Hautfarbe einmalig beurteilen ~ Das reicht für den Verlauf nicht.','-Zunehmenden Bauchumfang immer als Ernährungserfolg werten ~ Auch Aszites kann zunehmen.'),
 tq('Ein Patient mit Zirrhose erbricht Blut und wird schwindelig. Was folgt?','+Sofortige Notfallversorgung und Kreislaufbeurteilung ~ Eine schwere gastrointestinale Blutung ist möglich.','-Zuerst allein duschen lassen ~ Kreislaufkollaps ist möglich.','-Blut als normale Zirrhosefolge ignorieren ~ Es ist ein Notfallzeichen.','-Große orale Mengen bei Benommenheit geben ~ Schlucken und Atemweg sind gefährdet.'),
 tq('Bei Zirrhose wird eine Person neu verwirrt. Was ist richtig?','+Dringend Ursache abklären lassen ~ Enzephalopathie, Infektion oder Blutung sind möglich.','-Sicher nur eine psychische Reaktion ~ Das ist ohne Prüfung nicht begründbar.','-Eiweiß generell lebenslang vollständig streichen ~ Ernährung muss individuell geplant werden.','-Sedierung ohne Ursachenprüfung fordern ~ Sie kann die Beurteilung erschweren.')]);
disease('pancreatitis','Akute Pankreatitis','Verdauung','acute-pancreatitis','Akute Entzündung der Bauchspeicheldrüse; schwere systemische Verläufe sind möglich.','Starker anhaltender Oberbauchschmerz, teils zum Rücken|Übelkeit und Erbrechen|Fieber und Kreislaufprobleme möglich','Schmerz, Kreislauf, Atmung und Bilanz überwachen|Analgesie und angeordnete Flüssigkeitstherapie begleiten|Ernährung nach Verträglichkeit und Behandlungsplan, keine pauschale lange Karenz','Zunehmende Atemnot, Hypotonie oder Bewusstseinsveränderung verlangen sofortige Eskalation.',[
 tq('Welche Beschwerden passen zu akuter Pankreatitis?','+Starker Oberbauchschmerz mit möglicher Rückenausstrahlung ~ Das ist eine typische Schmerzkonstellation.','+Übelkeit und Erbrechen ~ Beides kann begleitend auftreten.','-Nur schmerzloser Harndrang ~ Das ist nicht typisch.','-Fehlende Gelbsucht schließt sie aus ~ Gelbsucht ist keine Voraussetzung.'),
 tq('Welche Aussage trifft zu?','+Eine schwere Pankreatitis kann mehrere Organe beeinträchtigen ~ Systemische Komplikationen sind möglich.','-Die Erkrankung bleibt immer rein lokal ~ Kreislauf und Atmung können betroffen sein.','-Schmerzfreiheit schließt jede Komplikation aus ~ Der Gesamtzustand bleibt wichtig.','-Alle Verläufe sind identisch ~ Schweregrade unterscheiden sich.'),
 tq('Bei Pankreatitis sinkt der Blutdruck und die Atemnot nimmt zu. Was tust du?','+Sofortige strukturierte Beurteilung und Eskalation ~ Organfunktionsstörungen sind möglich.','+Bilanz und bisherige Therapie übermitteln ~ Das unterstützt weitere Entscheidungen.','-Nur den Schmerzscore erheben ~ Atmung und Kreislauf haben jetzt Vorrang.','-Infusion eigenständig beliebig beschleunigen ~ Volumentherapie muss gesteuert werden.'),
 tq('Welche Aussage zur Versorgung ist richtig?','+Analgesie und Ernährung werden individuell geplant ~ Wirkung und Verträglichkeit zählen.','-Allen wochenlange Nahrungskarenz empfehlen ~ Das ist kein allgemeiner Standard.','-Schmerzmittel grundsätzlich vermeiden ~ Unbehandelter Schmerz belastet erheblich.','-Flüssigkeitsbilanz ist unwichtig ~ Verluste und Therapie müssen beurteilt werden.')]);
disease('gibleed','Gastrointestinale Blutung','Verdauung','vomiting-blood','Blutung im Verdauungstrakt; Schwere und Ursache müssen rasch beurteilt werden.','Bluterbrechen oder kaffeesatzartiges Erbrechen|Teerstuhl oder frisches Blut je nach Quelle|Blässe, Tachykardie, Schwindel bei Blutverlust','Kreislauf, Bewusstsein und Atemweg nach Dringlichkeit beurteilen|Notfallversorgung, Diagnostik und Therapie unterstützen|Blutungsmenge, Verlauf und Medikamente weitergeben','Bluterbrechen mit Kreislaufstörung ist ein Notfall. Ein zunächst normaler Blutdruck schließt relevanten Blutverlust nicht aus.',[
 tq('Welche Beobachtung kann eine obere gastrointestinale Blutung anzeigen?','+Kaffeesatzartiges Erbrechen ~ Verändertes Blut kann so aussehen.','+Teerschwarzer Stuhl ~ Verdautes Blut ist eine mögliche Ursache.','-Jeder dunkle Stuhl beweist eine Blutung ~ Auch Eisenpräparate können verfärben.','-Nur hellrotes Blut ist relevant ~ Auch verändertes Blut ist bedeutsam.'),
 tq('Welche Medikamenteninformation ist besonders wichtig?','+Antikoagulanzien und NSAR ~ Sie können Blutungsrisiken beeinflussen.','+Letzte Einnahme und Dosis ~ Das unterstützt die Akutbehandlung.','-Nur der Handelsname ohne Wirkstoffprüfung ~ Eine genaue Zuordnung ist nötig.','-Rezeptfreie Mittel müssen nicht genannt werden ~ Auch sie können relevant sein.'),
 tq('Eine Person erbricht Blut, ist kaltschweißig und schwindelig. Was folgt?','+Sofort Notfallhilfe und ABCDE ~ Schock und Atemwegsgefährdung sind möglich.','+Bei der Person bleiben und eng überwachen ~ Der Zustand kann rasch kippen.','-Zuerst einen Gehversuch durchführen ~ Das erhöht das Kollapsrisiko.','-Nur das Erbrochene entsorgen und später melden ~ Wesentliche Informationen gingen verloren.'),
 tq('Was ist bei der Übergabe wichtig?','+Art, Zeitpunkt und Verlauf der Blutungszeichen ~ Das macht die Situation einschätzbar.','+Vitalwerte, Bewusstsein und relevante Medikamente ~ Sie beeinflussen die Dringlichkeit.','-Eine geschätzte Ursache als sicher ausgeben ~ Diagnose und Beobachtung müssen getrennt werden.','-Normaler Blutdruck als einzige Entwarnung ~ Kompensation kann Blutverlust verdecken.')]);
disease('sepsis','Sepsis','Notfälle und Infektion','sepsis','Lebensbedrohliche Organdysfunktion durch eine fehlregulierte Reaktion auf eine Infektion.','Neue Verwirrtheit oder schwere Schwäche|Tachypnoe, Kreislaufstörung oder wenig Urin|Fieber, Untertemperatur oder auch normale Temperatur','Bei Verdacht unverzüglich eskalieren und strukturiert beurteilen|Infektionshinweise, Vitalwerte und Organzeichen übermitteln|Angeordnete Diagnostik und Therapie ohne vermeidbare Verzögerung unterstützen','Sepsis ist nicht gleich Fieber. Fehlendes Fieber oder ein niedriger Score schließt sie nicht sicher aus.',[
 tq('Welche Kombination begründet Sepsisverdacht?','+Infektionszeichen mit neuer Verwirrtheit und Hypotonie ~ Das spricht für mögliche Organdysfunktion.','+Infektion mit Tachypnoe und deutlich weniger Urin ~ Mehrere Organsysteme können betroffen sein.','-Nur hohes Fieber erlaubt einen Verdacht ~ Fieber kann fehlen.','-Ein einzelner niedriger Score schließt Sepsis sicher aus ~ Klinische Warnzeichen bleiben wichtig.'),
 tq('Was beschreibt Sepsis korrekt?','+Gefährliche fehlregulierte Reaktion auf Infektion mit Organdysfunktion ~ Das ist mehr als eine lokale Infektion.','-Jede Bakterie im Urin ist bereits Sepsis ~ Klinischer Zustand und Organfunktion sind entscheidend.','-Eine ausschließlich durch Viren ausgelöste Allergie ~ Das ist ein anderer Mechanismus.','-Immer ein sichtbarer roter Strich am Arm ~ Dieses Zeichen ist keine Voraussetzung.'),
 tq('Bei Harnwegsinfektion wird eine Person verwirrt und kreislaufinstabil. Was folgt?','+Sofortige Notfalleskalation ~ Eine Sepsis muss dringend behandelt werden.','+Aktuelle Werte, Verlauf und vermutete Infektionsquelle übermitteln ~ Das hilft bei gezielter Versorgung.','-Auf einen bestätigten Blutkulturbericht warten ~ Behandlung darf nicht so verzögert werden.','-Fieber erst senken und dann über Hilfe entscheiden ~ Instabilität hat sofortige Priorität.'),
 tq('Welche Aussage zu frühen Maßnahmen ist richtig?','+Diagnostik und Therapie werden nach Dringlichkeit koordiniert ~ Unnötige Verzögerung soll vermieden werden.','-Jede Person erhält unabhängig vom Zustand dieselbe große Flüssigkeitsmenge ~ Volumen braucht individuelle Steuerung.','-Antibiotika können ohne jede Anordnung frei gewählt werden ~ Therapie erfordert die zuständige medizinische Entscheidung.','-Nach einmaliger Besserung endet die Verlaufskontrolle ~ Organdysfunktion kann sich weiterentwickeln.')]);
disease('anaphylaxis','Anaphylaxie','Notfälle und Infektion','anaphylaxis','Rasch auftretende schwere systemische Überempfindlichkeitsreaktion mit möglicher Atemwegs- oder Kreislaufgefährdung.','Schwellung von Zunge oder Hals, Heiserkeit|Atemnot, Giemen und Kreislaufabfall|Hautzeichen möglich, aber nicht zwingend','Sofort Hilfe alarmieren und Auslöserkontakt soweit möglich beenden|Adrenalin intramuskulär nach Notfallstandard und Qualifikation priorisieren|Lagerung dem Zustand anpassen, nicht aufstehen oder herumlaufen lassen','Antihistaminika ersetzen bei Atemwegs- oder Kreislaufbeteiligung nicht die zeitkritische Adrenalingabe.',[
 tq('Welche Befunde nach Medikamentengabe sprechen für Anaphylaxie?','+Neue Heiserkeit und Atemnot ~ Der Atemweg kann bedroht sein.','+Kreislaufabfall mit Schwindel ~ Eine systemische Reaktion ist möglich.','-Fehlender Hautausschlag schließt sie aus ~ Hautzeichen müssen nicht vorhanden sein.','-Nur Juckreiz beweist bereits einen Schock ~ Der Gesamtzustand ist entscheidend.'),
 tq('Welches Medikament hat bei schwerer Anaphylaxie zentrale Akutbedeutung?','+Intramuskuläres Adrenalin nach Notfallstandard ~ Es behandelt lebensbedrohliche Atemwegs- und Kreislaufprobleme.','-Nur ein orales Antihistaminikum ~ Das ersetzt Adrenalin nicht.','-Ein frei ausgewähltes Antibiotikum ~ Es behandelt den Mechanismus nicht.','-Eine zusätzliche Dosis des vermuteten Auslösers ~ Das kann die Reaktion verschlimmern.'),
 tq('Nach einer Infusion treten Atemnot und Hypotonie auf. Welche Schritte passen?','+Infusion mit möglichem Auslöser stoppen und Hilfe holen ~ Weitere Exposition soll vermieden werden.','+ABCDE und Notfalltherapie nach Standard ~ Die Situation kann rasch lebensbedrohlich werden.','-Allein zur Toilette gehen lassen ~ Aufstehen kann den Kreislauf gefährden.','-Erst eine Hautreaktion abwarten ~ Atemwegs- und Kreislaufzeichen reichen zur Dringlichkeit.'),
 tq('Nach anfänglicher Besserung fragt die Person, ob sie sofort gehen kann. Was ist richtig?','+Weitere medizinische Überwachung nach Risiko ist nötig ~ Reaktionen können erneut auftreten.','+Notfallplan und Auslöservermeidung besprechen ~ Das unterstützt die spätere Sicherheit.','-Besserung macht jede Nachbeobachtung unnötig ~ Das ist keine sichere Schlussfolgerung.','-Den Auslöser ohne Prüfung erneut ausprobieren ~ Das kann gefährlich sein.')]);
disease('pressure','Dekubitus','Haut und Bewegung','pressure-sores','Lokaler Haut- oder Gewebeschaden durch Druck beziehungsweise Druck zusammen mit Scherkräften.','Nicht wegdrückbare Verfärbung bei intakter Haut möglich|Schmerz oder veränderte Temperatur und Konsistenz|Tiefe Schädigung auch bei unauffälliger Oberfläche möglich','Risiko klinisch beurteilen, Eigenbewegung fördern|Druck gezielt entlasten und Positionen individuell planen|Hautbefund, Schmerz und Wirkung wiederholt bewerten','Gerötete gefährdete Stellen nicht massieren; ein Hilfsmittel ersetzt keine Evaluation.',[
 tq('Welcher Befund entspricht Dekubitus Kategorie 1?','+Nicht wegdrückbare Rötung bei intakter Haut ~ Die Hautoberfläche ist noch geschlossen.','-Jede offene Wunde bis zum Knochen ~ Das entspricht nicht Kategorie 1.','-Jede wegdrückbare Rötung automatisch ~ Eine differenzierte Beurteilung ist nötig.','-Nur ein Bluterguss nach Sturz ~ Die Ursache und Merkmale unterscheiden sich.'),
 tq('Was ist bei dunkleren Hauttönen besonders wichtig?','+Auch Temperatur, Konsistenz, Schmerz und Farbänderungen beurteilen ~ Rötung kann schwerer erkennbar sein.','-Nur eine leuchtend rote Stelle gilt als Warnzeichen ~ Das würde Schäden übersehen.','-Hautbeobachtung ist unnötig ~ Risiken bestehen unabhängig vom Hautton.','-Ein Foto ersetzt jede klinische Einschätzung ~ Tast- und Schmerzbefunde fehlen dann.'),
 tq('Eine Ferse zeigt eine nicht wegdrückbare Rötung. Was planst du?','+Wirksame Druckentlastung und Verlaufskontrolle ~ Die Belastung muss reduziert werden.','+Individuelle Bewegungs- und Positionsplanung ~ Risiko und Verträglichkeit bestimmen die Maßnahmen.','-Kräftige Massage ~ Sie kann das gefährdete Gewebe zusätzlich schädigen.','-Für alle exakt denselben starren Zeitplan ~ Reaktionen und Bedarf unterscheiden sich.'),
 tq('Welches Ergebnis zeigt Wirksamkeit besser als eine reine Maßnahmendokumentation?','+Hautbefund, Schmerz und Druckbelastung verbessern sich im Verlauf ~ Das beurteilt die Wirkung.','-Nur: Spezialmatratze bestellt ~ Eine Bestellung belegt noch keine Entlastung.','-Nur: Lagerungsplan ausgedruckt ~ Ein Plan ist kein Ergebnis.','-Nur die Anzahl der verwendeten Kissen ~ Sie sagt wenig über tatsächlichen Druck aus.')]);
disease('hip','Hüftnahe Femurfraktur','Haut und Bewegung','broken-hip','Knochenbruch im hüftnahen Bereich des Oberschenkels, häufig nach Sturz.','Hüft- oder Leistenschmerz|Belastung oft nicht möglich|Verkürztes oder außenrotiertes Bein möglich','Nach Sturz sicher versorgen, Schmerz und Neurovaskularität beurteilen|Keine erzwungene Belastungsprobe; Diagnostik organisieren|Nach Operation Mobilisation, Belastung und Bewegungsregeln individuell abstimmen','Nicht jeder Bruch zeigt eine sichtbare Fehlstellung. Neue Atemnot oder Kreislaufstörung erfordert sofortige Beurteilung.',[
 tq('Welche Befunde passen zu hüftnaher Femurfraktur?','+Hüftschmerz und fehlende Belastbarkeit nach Sturz ~ Ein Bruch muss ausgeschlossen werden.','+Verkürztes außenrotiertes Bein ~ Das kann auftreten, muss aber nicht.','-Fehlende Fehlstellung schließt jede Fraktur aus ~ Manche Brüche sind weniger auffällig.','-Nur ein offener Bruch verursacht Schmerzen ~ Auch geschlossene Frakturen schmerzen.'),
 tq('Was gehört zur Beobachtung nach einer Hüftoperation?','+Schmerz, Wunde und Kreislauf ~ Komplikationen sollen erkannt werden.','+Mobilität und akute Verwirrtheit ~ Funktion und Delirrisiko sind relevant.','-Nur der Operationstag entscheidet den Pflegebedarf ~ Zustand und Ressourcen sind maßgeblich.','-Jede Person hat dieselben Bewegungseinschränkungen ~ Verfahren und Anordnung unterscheiden sich.'),
 tq('Nach einem Sturz hat eine Bewohnerin starke Leistenschmerzen. Was tust du?','+Sichere Versorgung und rasche medizinische Abklärung ~ Eine Fraktur ist möglich.','-Mehrfach aufstehen lassen, um Sicherheit zu gewinnen ~ Das kann Schmerz und Schaden vergrößern.','-Bein gewaltsam in Normalstellung drehen ~ Das ist keine sichere Erstmaßnahme.','-Nur auf sichtbare Blutung prüfen ~ Auch geschlossene Verletzungen sind relevant.'),
 tq('Wie planst du die erste postoperative Mobilisation?','+Belastungsfreigabe, Schmerz und Kreislauf vorher klären ~ Sicherheit hängt vom individuellen Zustand ab.','+Passende Unterstützung und Hilfsmittel vereinbaren ~ Ressourcen und Risiken werden berücksichtigt.','-Dauerhafte Bettruhe zur allgemeinen Frakturprophylaxe ~ Immobilität verursacht zusätzliche Risiken.','-Ungeprüft volle Belastung für alle ~ Die Freigabe kann unterschiedlich sein.')]);
disease('osteoporosis','Osteoporose','Haut und Bewegung','osteoporosis','Verminderte Knochenfestigkeit mit erhöhtem Risiko für Fragilitätsfrakturen.','Lange symptomlos möglich|Brüche nach geringer Belastung|Wirbelbrüche können Rückenbeschwerden und Größenverlust verursachen','Sturzrisiken und sichere Bewegung gemeinsam bearbeiten|Ernährung und verordnete knochenspezifische Therapie begleiten|Neue Schmerzen nach Bagatelltrauma abklären lassen','Schmerzfreiheit bedeutet nicht stabile Knochen; neue starke Rückenschmerzen können einen Wirbelbruch anzeigen.',[
 tq('Welche Aussage trifft zu Osteoporose zu?','+Die Knochenbruchgefährdung ist erhöht ~ Die Knochenfestigkeit ist vermindert.','+Sie kann bis zur ersten Fraktur unbemerkt bleiben ~ Frühe Beschwerden fehlen oft.','-Sie ist identisch mit Gelenkverschleiß ~ Arthrose betrifft primär Gelenke.','-Ohne Schmerz gibt es kein Frakturrisiko ~ Schmerzfreiheit schließt es nicht aus.'),
 tq('Welche Frakturen sind typisch?','+Wirbelkörperfrakturen ~ Auch geringe Belastungen können genügen.','+Hüft- und handgelenksnahe Frakturen ~ Sie sind häufige Fragilitätsfrakturen.','-Nur Schädelbrüche sind möglich ~ Das ist nicht der typische Schwerpunkt.','-Jede Fraktur beweist allein Osteoporose ~ Trauma und weitere Diagnostik zählen.'),
 tq('Eine Person entwickelt nach geringem Heben starke neue Rückenschmerzen. Was folgt?','+Frakturverdacht medizinisch abklären lassen ~ Eine Wirbelkörperfraktur ist möglich.','-Ohne Sturz ist ein Bruch ausgeschlossen ~ Geringe Belastung kann ausreichen.','-Schmerzhaftes Training sofort erzwingen ~ Das kann bei Fraktur ungeeignet sein.','-Als normale Alterung abtun ~ Neue Schmerzen sind erklärungsbedürftig.'),
 tq('Welche Maßnahmen sind sinnvoll?','+Sichere angepasste Kraft- und Gleichgewichtsaktivität ~ Bewegung kann Funktion und Sturzschutz fördern.','+Medikamentenplan und konkrete Einnahmehinweise beachten ~ Präparate unterscheiden sich.','-Alle Bewegung aus Angst dauerhaft vermeiden ~ Das kann Muskelkraft vermindern.','-Kalzium und Vitamin D beliebig hoch dosieren ~ Bedarf und Verordnung sind zu prüfen.')]);
disease('depression','Depressive Erkrankung','Psychische Gesundheit','../mental-health/conditions/depression-in-adults/overview','Psychische Erkrankung mit anhaltend gedrückter Stimmung und/oder Interessenverlust sowie weiteren Beschwerden.','Antriebs- und Interessenverlust|Schlaf-, Appetit- oder Konzentrationsprobleme|Hoffnungslosigkeit und mögliche Suizidgedanken','Wertschätzend zuhören und Belastungen erfragen|Erreichbare Tagesstruktur und Behandlung unterstützen|Suizidalität direkt ansprechen und nach Risiko eskalieren','Konkrete Suizidabsicht oder akute Selbstgefährdung erfordert sofortige professionelle Hilfe und Begleitung.',[
 tq('Welche Befunde passen zu Depression?','+Anhaltender Interessenverlust und gedrückte Stimmung ~ Beides sind zentrale mögliche Symptome.','+Schlaf- und Konzentrationsstörungen ~ Auch körpernahe Beschwerden kommen vor.','-Jede kurze Traurigkeit ist eine depressive Erkrankung ~ Dauer, Ausprägung und Kontext zählen.','-Betroffene könnten sich einfach zusammenreißen ~ Depression ist eine behandlungsbedürftige Erkrankung.'),
 tq('Was ist bei der Äußerung „Es hat alles keinen Sinn mehr“ fachlich angemessen?','+Suizidgedanken offen und direkt erfragen ~ Das unterstützt die Gefährdungseinschätzung.','+Die Aussage ernst nehmen ~ Hoffnungslosigkeit kann relevant sein.','-Das Thema grundsätzlich vermeiden ~ Dadurch wird Risiko nicht geklärt.','-Absolute Geheimhaltung versprechen ~ Bei Gefahr muss Hilfe ermöglicht werden.'),
 tq('Eine Person nennt einen konkreten Suizidplan und aktuelle Absicht. Was folgt?','+Sofortige fachliche Krisenbeurteilung organisieren ~ Akute Selbstgefährdung ist möglich.','+Begleiten und Schutz nach Standard sicherstellen ~ Die Person soll nicht unversorgt bleiben.','-Allein nach Hause schicken ~ Das kann gefährlich sein.','-Nur ein Versprechen verlangen und die Betreuung beenden ~ Das ersetzt keine Risikobeurteilung.'),
 tq('Welche Unterstützung ist bei stark vermindertem Antrieb passend?','+Kleine vereinbarte Schritte und realistische Aktivität ~ Überforderung wird vermieden.','+Wirkung, Belastung und Therapie im Verlauf besprechen ~ Unterstützung muss angepasst werden.','-Vorwürfe wegen mangelnder Leistung ~ Das kann Schuldgefühle verstärken.','-Alle Entscheidungen dauerhaft abnehmen ~ Selbstbestimmung und Fähigkeiten bleiben wichtig.')]);
disease('schizophrenia','Schizophrenie','Psychische Gesundheit','../mental-health/conditions/schizophrenia/overview','Psychische Erkrankung mit möglichen psychotischen Symptomen und Beeinträchtigungen von Denken, Antrieb und Alltag.','Wahn oder Halluzinationen|Desorganisiertes Denken möglich|Antriebsmangel und sozialer Rückzug','Ruhig, klar und verlässlich kommunizieren|Erleben ernst nehmen, Wahninhalte nicht bestätigen|Risiko, Bedürfnisse und Nebenwirkungen der Behandlung beurteilen','Befehlende Stimmen mit Selbst- oder Fremdgefährdung benötigen sofortige fachliche Beurteilung.',[
 tq('Welche Aussagen sind richtig?','+Halluzinationen und Wahn können vorkommen ~ Sie gehören zu möglichen psychotischen Symptomen.','+Auch Rückzug und Antriebsmangel sind möglich ~ Nicht nur auffällige Positivsymptome zählen.','-Schizophrenie bedeutet gespaltene Persönlichkeit ~ Das ist ein verbreiteter Irrtum.','-Die Diagnose beweist Gewalttätigkeit ~ Individuelles Verhalten muss beurteilt werden.'),
 tq('Welche Gesprächsreaktion ist angemessen, wenn eine Person Stimmen hört?','+„Ich höre sie nicht; ich sehe, dass Sie belastet sind.“ ~ Das verbindet Realität und Empathie.','-„Ja, ich höre dieselben Verfolger.“ ~ Das bestätigt die Wahrnehmung unzutreffend.','-„Sie erfinden alles.“ ~ Das beschämt und erschwert Beziehung.','-Lange konfrontative Beweisdebatte erzwingen ~ Das kann Anspannung erhöhen.'),
 tq('Eine Person berichtet Stimmen mit Aufforderung zur Selbstverletzung. Was folgt?','+Inhalt, Handlungsdruck und aktuelle Sicherheit klären ~ Die konkrete Gefährdung muss eingeschätzt werden.','+Sofort fachliche Hilfe nach Dringlichkeit organisieren ~ Schutz und Behandlung sind erforderlich.','-Die Aussage als typisches Symptom ignorieren ~ Auch bekannte Symptome können akut gefährlich sein.','-Absolute Geheimhaltung zusagen ~ Bei Gefahr muss Unterstützung möglich bleiben.'),
 tq('Unter antipsychotischer Therapie treten hohes Fieber, Muskelstarre und Bewusstseinstrübung auf. Was tust du?','+Unverzüglich medizinisch eskalieren ~ Eine schwere Arzneimittelreaktion ist möglich.','-Als gewünschten Beruhigungseffekt bewerten ~ Diese Zeichen sind nicht harmlos.','-Eigenständig eine weitere Dosis geben ~ Das könnte gefährlich sein.','-Nur für den nächsten Monat dokumentieren ~ Die Konstellation ist zeitkritisch.')]);
disease('leukaemia','Akute Leukämie und Neutropenie','Onkologie','acute-myeloid-leukaemia','Bösartige Erkrankung der Blutbildung; gesunde Blutzellreihen können verdrängt werden. Die genaue Form bestimmt die Therapie.','Blässe und Erschöpfung bei Anämie|Infektanfälligkeit bei gestörter Immunabwehr|Blutungszeichen bei Thrombozytopenie','Blutbild und individuellen Behandlungsplan berücksichtigen|Infektions- und Blutungszeichen beobachten|Mundpflege, Ernährung und psychosoziale Unterstützung abstimmen','Fieber oder akute Verschlechterung bei Neutropenie erfordert sofortige onkologische Notfallabklärung.',[
 tq('Welche Zusammenhänge sind plausibel?','+Anämie kann Müdigkeit und Belastungsatemnot erklären ~ Erythrozyten transportieren Sauerstoff.','+Thrombozytopenie kann Blutungen begünstigen ~ Thrombozyten unterstützen die Blutstillung.','-Viele Leukozyten bedeuten immer gute Abwehr ~ Krankhaft veränderte Zellen können funktionsgestört sein.','-Alle Leukämien haben dieselbe Therapie ~ Formen und Risikoprofile unterscheiden sich.'),
 tq('Welche Beobachtungen sind besonders relevant?','+Fieber und neue Infektzeichen ~ Immunsuppression erhöht die Gefährdung.','+Petechien oder Schleimhautblutungen ~ Eine Gerinnungs- oder Thrombozytenstörung ist möglich.','-Nur das Körpergewicht einmalig ~ Das erfasst die akuten Risiken nicht.','-Unauffällige Haut schließt jede Infektion aus ~ Infektionen können anders sichtbar werden.'),
 tq('Ein Kind unter Chemotherapie mit Neutropenie hat Fieber und wirkt ungewöhnlich still. Was folgt?','+Sofort das onkologische Team nach Notfallstandard alarmieren ~ Eine schwere Infektion muss rasch behandelt werden.','+Vitalfunktionen erheben, ohne Alarmierung zu verzögern ~ Das unterstützt die Akutversorgung.','-Bis zur nächsten Visite warten ~ Verzögerung kann gefährlich sein.','-Nur Fiebermittel und Entwarnung ~ Die Ursache bleibt ungeklärt.'),
 tq('Bei ausgeprägter Thrombozytopenie: Welche Planung passt?','+Blutungszeichen und verletzungsarme Mundpflege beachten ~ Schleimhäute sind gefährdet.','+Invasive Maßnahmen auf Indikation und Sicherheitsvorgaben prüfen ~ Blutungsrisiken müssen berücksichtigt werden.','-Intramuskuläre Injektionen ungeprüft fortführen ~ Hämatome können entstehen.','-Alle Kontakte und jede Bewegung pauschal verbieten ~ Schutz wird individuell geplant.')]);
disease('bronchiolitis','Bronchiolitis bei Säuglingen','Pädiatrie','bronchiolitis','Meist virale Infektion kleiner Atemwege bei Säuglingen und Kleinkindern, häufig durch RSV.','Schnupfen und Husten|Beschleunigte oder angestrengte Atmung|Trinkschwäche, bei kleinen Säuglingen Apnoen möglich','Atemarbeit, Trinkmenge und nasse Windeln beurteilen|Sichere altersgerechte Unterstützung und Verlaufskontrolle|Bei deutlicher Atemnot oder Apnoe sofort pädiatrische Notfallversorgung','Atempausen, Zyanose, Erschöpfung oder schlechte Weckbarkeit sind Notfallzeichen.',[
 tq('Welche Befunde passen zu Bronchiolitis?','+Husten mit beschleunigter Atmung bei einem Säugling ~ Kleine Atemwege können betroffen sein.','+Trinkschwäche ~ Atemarbeit kann die Nahrungsaufnahme erschweren.','-Jeder Fall muss hohes Fieber haben ~ Fieber kann gering sein oder fehlen.','-Nur Jugendliche erkranken ~ Typisch sind kleine Kinder.'),
 tq('Welche Beobachtungen helfen bei der Schwereeinschätzung?','+Einziehungen, Atempausen und Wachheit ~ Sie zeigen Atem- und Allgemeinzustand.','+Trinkmenge und nasse Windeln ~ Sie geben Hinweise auf Versorgung und Hydratation.','-Nur die Lautstärke des Hustens ~ Sie reicht zur Beurteilung nicht aus.','-Ein einzelnes Lächeln schließt Gefährdung aus ~ Der Gesamtverlauf bleibt entscheidend.'),
 tq('Ein Säugling zeigt Atempausen und ist schwer weckbar. Was tust du?','+Sofort pädiatrische Notfallhilfe und Vitalfunktionen beurteilen ~ Atemversagen ist möglich.','-Erst die nächste volle Flasche erzwingen ~ Bei Atemnot besteht Aspirationsgefahr.','-Nur schlafen lassen ~ Schlechte Weckbarkeit ist ein Warnsignal.','-Erwachsenendosis eines Hustenmittels geben ~ Das ist gefährlich und ungeeignet.'),
 tq('Welche Aussage zur Elternberatung ist richtig?','+Konkrete Warnzeichen und Rückmeldewege erklären ~ Verschlechterung soll früh erkannt werden.','+Trinken und Ausscheidung im Verlauf beachten ~ Dehydratation kann entstehen.','-Antibiotika sind bei jedem viralen Verlauf nötig ~ Die Indikation wird medizinisch geprüft.','-Auf dem Bauch schlafen lassen als Routineempfehlung ~ Sicherer Säuglingsschlaf bleibt zu beachten.')]);
const competencyQuestions=[];
function kb(group,items){items.forEach((item,i)=>{const [topic,sources,v]=item;competencyQuestions.push({...v,id:'k'+group+'-'+(i+1),kind:'competency',group:String(group),topic,sources:sources.split(','),level:i<8?'Verstehen':'Anwenden'})})}
kb(1,[
 ['Pflegeprozess','process',tq('Welche Reihenfolge beschreibt das Sechs-Schritt-Modell nach Fiechter und Meier korrekt?','+Informationen sammeln → Probleme und Ressourcen erkennen → Ziele festlegen → Maßnahmen planen → durchführen → evaluieren ~ Die Schritte bilden einen wiederkehrenden Pflegeprozess.','-Ziele → Durchführung → Informationen → Evaluation → Planung → Ressourcen ~ Das überspringt die Begründung der Planung.','-Diagnose → Therapie → Abrechnung ~ Das ist nicht dieses Pflegeprozessmodell.','-Erleben → Handeln → Dokumentieren ~ Das benennt die sechs Schritte nicht korrekt.')],
 ['Informationssammlung','process',tq('Welche Angaben gehören in eine personenzentrierte Informationssammlung?','+Wünsche und subjektives Erleben der Person ~ Die Perspektive der Person ist wichtig.','+Beobachtungen und erhaltene Fähigkeiten ~ Ressourcen ergänzen Probleme.','-Nur die ärztliche Diagnosenliste ~ Sie ersetzt das pflegerische Assessment nicht.','-Ungeprüfte Vermutungen als gesicherte Tatsachen ~ Beobachtung und Interpretation müssen unterscheidbar bleiben.')],
 ['Pflegediagnostik','nanda',tq('Welche Aussage unterscheidet eine Pflegediagnose von einer medizinischen Diagnose?','+Sie beschreibt pflegerelevante Reaktionen oder Risiken ~ Der Fokus liegt auf menschlichen Reaktionen und Unterstützungsbedarf.','-Sie darf nur den Namen einer Erkrankung wiederholen ~ Das bildet den Pflegebedarf nicht ausreichend ab.','-Sie ersetzt medizinische Diagnostik ~ Beide Perspektiven ergänzen sich.','-Sie ist unabhängig von Assessmentdaten ~ Sie muss fachlich begründet sein.')],
 ['PES','nanda',tq('Welche Angaben bilden eine problemfokussierte PES-Beschreibung?','+Problem, Einflussfaktoren und Symptome ~ Sie verbinden Reaktion, Zusammenhang und Belege.','-Problem, Medikament und Stationsname ~ Das ist kein PES-Schema.','-Nur ein Risiko ohne beobachtete Symptome ~ Das betrifft eine andere Diagnoseart.','-Eine Vermutung ohne Befund ~ Eine problemfokussierte Diagnose braucht Belege.')],
 ['Risikodiagnose','nanda',tq('Was ist bei einer Risikopflegediagnose zu beachten?','+Risikofaktoren müssen begründet sein ~ Sie beschreiben die Anfälligkeit.','+Es liegen noch keine Symptome des benannten Problems vor ~ Sonst wäre eine problemfokussierte Beurteilung nötig.','-Symptome müssen erfunden werden, damit PES vollständig ist ~ Das wäre fachlich falsch.','-Risiken brauchen keine Maßnahmen ~ Prävention kann gerade hier nötig sein.')],
 ['Ziele','process',tq('Welche Formulierung ist ein überprüfbares Pflegeziel?','+Frau K. nennt bis morgen zwei vereinbarte Schritte beim sicheren Aufstehen und demonstriert sie mit Unterstützung. ~ Person, Ergebnis und Zeitpunkt sind benannt.','-Dreimal täglich mobilisieren. ~ Das beschreibt eine Maßnahme.','-Es soll besser werden. ~ Ergebnis und Zeitpunkt fehlen.','-Alle bleiben immer sturzfrei, unabhängig vom Risiko. ~ Die Formulierung ist pauschal und unrealistisch.')],
 ['Maßnahmenplanung','process',tq('Welche Angaben machen eine Pflegemaßnahme nachvollziehbar?','+Wer was wann und wie mit welcher Unterstützung tut ~ Die Durchführung wird konkret.','+Individueller Bedarf und geplanter Wirksamkeitscheck ~ Maßnahme und Ziel müssen zusammenpassen.','-Nur „nach Bedarf“ ohne Kriterien ~ Das lässt wichtige Entscheidungen offen.','-Ein identischer Plan für jede Person ~ Ressourcen und Risiken unterscheiden sich.')],
 ['Evaluation','process',tq('Was gehört zur Evaluation?','+Erreichte Ergebnisse mit vereinbarten Zielen vergleichen ~ So wird Wirkung erkennbar.','+Bei Abweichungen Ursachen und Plan prüfen ~ Der Prozess wird angepasst.','-Nur bestätigen, dass jede Maßnahme abgehakt ist ~ Durchführung beweist keine Wirksamkeit.','-Unerreichte Ziele grundsätzlich der Person anlasten ~ Auch Planung und Bedingungen sind zu prüfen.')],
 ['Ressourcen','process',tq('Herr M. kann sein Gesicht selbst waschen, benötigt aber Hilfe am Rücken. Welche Planung passt?','+Selbstständige Teilhandlungen ermöglichen und gezielt ergänzen ~ Fähigkeiten werden erhalten.','-Die gesamte Körperpflege ungefragt übernehmen ~ Das fördert die Ressource nicht.','-Jede Hilfe verweigern ~ Der tatsächliche Bedarf bleibt unversorgt.','-Nur die Diagnose im Plan notieren ~ Konkrete Fähigkeiten fehlen.')],
 ['Schmerzassessment','pain,standards',tq('Eine auskunftsfähige Patientin nennt NRS 8, lächelt aber. Was ist richtig?','+Selbstauskunft ernst nehmen und differenziert erfassen ~ Verhalten kann Schmerz verbergen.','+Therapie und Wirkung passend überprüfen ~ Hoher Schmerz erfordert Reaktion.','-Lächeln beweist Schmerzfreiheit ~ Das ist kein sicherer Schluss.','-Den Wert ungefragt auf 2 korrigieren ~ Das entwertet die Selbstauskunft.')],
 ['BESD','pain',tq('Welche Aussagen zur BESD treffen zu?','+Sie beurteilt beobachtbares schmerzbezogenes Verhalten ~ Sie unterstützt bei eingeschränkter Kommunikation.','+Ein Wert von 0 schließt Schmerz nicht sicher aus ~ Beobachtungszeichen können fehlen.','-BESD 6 bedeutet exakt dieselbe Intensität wie NRS 6 ~ Die Skalen sind nicht direkt gleichzusetzen.','-Sie ersetzt immer jeden Versuch der Selbstauskunft ~ Mögliche Selbstauskunft bleibt wichtig.')],
 ['Sturzprävention','standards',tq('Ein Bewohner stürzt wiederholt nachts auf dem Toilettenweg. Was gehört zur Planung?','+Sturzhergang, Harndrang, Medikamente und Umgebung prüfen ~ Risiken können mehrere Ursachen haben.','+Mit ihm einen sicheren Toilettenweg und Hilfebedarf vereinbaren ~ Die Planung soll alltagstauglich sein.','-Allen Bewohnern nachts Bewegung verbieten ~ Das ist keine individuelle Prävention.','-Nur einen Score dokumentieren und nichts ändern ~ Assessment braucht Konsequenzen.')],
 ['Dekubitusprävention','standards',tq('Welche Kombination macht eine Dekubitusplanung wirksam?','+Individuelle Druckentlastung und Bewegungsförderung ~ Die Belastung wird reduziert.','+Hautreaktion und Verträglichkeit regelmäßig prüfen ~ Maßnahmen müssen angepasst werden.','-Jede Rötung kräftig massieren ~ Gefährdetes Gewebe kann geschädigt werden.','-Spezialmatratze ersetzt jede weitere Beurteilung ~ Das Hilfsmittel ist nur ein Baustein.')],
 ['Ernährung','process',tq('Eine Patientin nimmt ungewollt ab und lässt Mahlzeiten stehen. Was klärst du?','+Gewichtsverlauf, Aufnahme und mögliche Ursachen ~ Mangelernährung muss differenziert beurteilt werden.','+Vorlieben, Mundprobleme, Schlucken und Unterstützung ~ Ursachen können behandelbar sein.','-Nur den BMI, der weitere Verlauf ist unnötig ~ Auch Gewichtsverlust kann relevant sein.','-Alle Speisen ohne Rückfrage pürieren ~ Anpassung benötigt individuelle Begründung.')],
 ['Dysphagie','process',tq('Beim Essen tritt eine feuchte Stimme mit Husten auf. Was passt?','+Gabe unterbrechen, Atmung prüfen und Schluckabklärung organisieren ~ Aspiration ist möglich.','-Schneller weiterfüttern, um die Mahlzeit zu beenden ~ Das erhöht die Gefahr.','-Ein Strohhalm ist grundsätzlich sicher ~ Hilfsmittel müssen individuell geprüft werden.','-Eine fehlende Hustenreaktion schließt Aspiration aus ~ Stille Aspiration ist möglich.')],
 ['Kontinenz','standards',tq('Welche Maßnahmen unterstützen Kontinenz personenzentriert?','+Ausscheidungsmuster und beeinflussbare Ursachen erfassen ~ Der Bedarf ist individuell.','+Toilettenzugang und passende Unterstützung vereinbaren ~ Selbstständigkeit soll gefördert werden.','-Flüssigkeit für alle stark einschränken ~ Das kann schaden.','-Ein Dauerkatheter ist immer die erste Wahl ~ Er benötigt eine begründete Indikation.')],
 ['Akutsituation','abcde',tq('Eine Person ist nicht ansprechbar und atmet nicht normal. Was hat Vorrang?','+Notfallhilfe und Reanimation nach aktuellem Standard ~ Ein Kreislaufstillstand ist möglich.','-Zuerst eine vollständige Pflegeanamnese ~ Das verzögert lebensrettende Maßnahmen.','-Nur stabile Seitenlage ~ Fehlende normale Atmung erfordert Reanimation.','-Erst eine schriftliche ärztliche Anordnung abwarten ~ Die Notfallversorgung muss beginnen.')],
 ['Pädiatrische Pflege','each',tq('Ein Kind fürchtet eine notwendige Untersuchung. Welche Schritte passen?','+Altersgerecht erklären und echte kleine Wahlmöglichkeiten bieten ~ Beteiligung vermindert Überforderung.','+Vertraute Bezugsperson nach Situation einbeziehen ~ Sicherheit und Bindung unterstützen Bewältigung.','-Versprechen, dass es garantiert nicht weh tut ~ Falsche Versprechen schaden Vertrauen.','-Über das Kind sprechen, ohne es anzusprechen ~ Die Perspektive des Kindes fehlt.')],
 ['Rehabilitation','icf',tq('Welche Planung folgt einer ICF-orientierten Perspektive?','+Körperfunktionen, Aktivitäten, Teilhabe und Kontext berücksichtigen ~ Funktionieren entsteht im Zusammenspiel.','+Das Ziel der Person, wieder den Garten zu erreichen, einbeziehen ~ Teilhabe wird konkret.','-Nur den Krankheitsnamen betrachten ~ Das erfasst den Alltag nicht.','-Personbezogene Faktoren sind vollständig als ICF-Kodes klassifiziert ~ Sie werden berücksichtigt, aber nicht so kodiert.')],
 ['Palliative Pflege','ethics,process',tq('Eine sterbende Person möchte vor allem weniger Atemnot und vertraute Begleitung. Was passt?','+Ziele und Symptomlinderung mit ihr und dem Team abstimmen ~ Ihre Prioritäten leiten die Versorgung.','+Wirkung der vereinbarten Maßnahmen wiederholt prüfen ~ Auch palliative Pflege wird evaluiert.','-Pflegeziele müssen immer vollständige Heilung verlangen ~ Ziele richten sich nach der Situation.','-Ein einmaliger Plan gilt unabhängig von Veränderungen ~ Bedürfnisse können sich ändern.')]
]);
kb(2,[
 ['Aktives Zuhören','law',tq('Was unterstützt aktives Zuhören?','+In eigenen Worten zusammenfassen und rückfragen ~ So kann Verständnis überprüft werden.','+Gefühle vorsichtig benennen ~ Die Person kann bestätigen oder korrigieren.','-Schon während der Antwort das Thema wechseln ~ Das unterbricht die Erkundung.','-Eigene Deutungen als Tatsache festlegen ~ Das kann am Erleben vorbeigehen.')],
 ['Offene Fragen','law',tq('Welche Frage eröffnet die Sicht der Person?','+„Was macht Ihnen beim Heimgehen Sorgen?“ ~ Sie lädt zu einer eigenen Darstellung ein.','-„Sie haben doch keine Angst?“ ~ Das ist suggestiv.','-„Sie nehmen das Medikament jetzt, ja?“ ~ Das lenkt auf Zustimmung.','-„Es ist alles klar, oder?“ ~ Das prüft Verständnis wenig zuverlässig.')],
 ['Teach-back','teach',tq('Wie wird Teach-back sinnvoll eingesetzt?','+Die Person erklärt den Plan mit eigenen Worten ~ Verständnis wird sichtbar.','+Unklarheiten erneut erklären und nochmals prüfen ~ Die Verantwortung für Verständlichkeit wird übernommen.','-Als benotete Gedächtnisprüfung der Person ~ Das verfehlt den unterstützenden Zweck.','-Nur ein Merkblatt unterschreiben lassen ~ Eine Unterschrift belegt kein Verständnis.')],
 ['Sprachmittlung','consent,law',tq('Bei einer komplexen Aufklärung besteht eine Sprachbarriere. Was ist angemessen?','+Geeignete qualifizierte Sprachmittlung organisieren ~ Verständlichkeit muss sichergestellt werden.','+Die Person weiterhin direkt ansprechen ~ Sie bleibt die Gesprächspartnerin.','-Ein kleines Kind standardmäßig übersetzen lassen ~ Rolle und Verlässlichkeit sind problematisch.','-Lauter sprechen ersetzt die Übersetzung ~ Lautstärke löst die Sprachbarriere nicht.')],
 ['Hörbeeinträchtigung','law',tq('Was unterstützt Kommunikation bei Hörbeeinträchtigung?','+Blickkontakt und ruhige Umgebung ~ Visuelle Hinweise und weniger Störschall helfen.','+Geeignete Hörhilfen und bevorzugten Kommunikationsweg klären ~ Bedarf und Möglichkeiten unterscheiden sich.','-Von hinten laut rufen als Standard ~ Das erschwert die Orientierung.','-Hörprobleme mit fehlender Einsicht gleichsetzen ~ Das ist eine unbegründete Zuschreibung.')],
 ['Aphasie','law',tq('Wie kommunizierst du mit einer Person mit Aphasie?','+Zeit lassen und geeignete Kommunikationshilfen nutzen ~ Sprache und Verstehen können unterschiedlich betroffen sein.','+Verständnis und gewünschte Hilfe individuell prüfen ~ Aphasie bedeutet nicht automatisch fehlende Urteilsfähigkeit.','-Für sie jedes Gespräch ohne Rückfrage beenden ~ Das nimmt Beteiligung.','-Grundsätzlich wie mit einem Kleinkind sprechen ~ Das ist nicht personengerecht.')],
 ['Gemeinsame Entscheidungen','ethics',tq('Was gehört zu gemeinsamer informierter Entscheidungsfindung?','+Möglichkeiten und Folgen verständlich besprechen ~ Grundlage ist ausreichende Information.','+Werte und Wünsche der Person berücksichtigen ~ Entscheidungen sollen zu ihr passen.','-Nur die bequemste Teamlösung anbieten ~ Das beschränkt Beteiligung.','-Angehörige entscheiden immer anstelle der Person ~ Selbstbestimmung bleibt maßgeblich.')],
 ['Ethik','ethics',tq('Welche Prinzipien werden häufig in der Prinzipienethik unterschieden?','+Autonomie und Nichtschaden ~ Selbstbestimmung und Schadensvermeidung zählen dazu.','+Wohltun und Gerechtigkeit ~ Nutzen und faire Behandlung zählen dazu.','-Gehorsam gegenüber jeder Anweisung als oberstes Prinzip ~ Anweisungen müssen fachlich und rechtlich geprüft werden.','-Wirtschaftlichkeit ersetzt alle Rechte ~ Rechte bleiben verbindlich.')],
 ['Ablehnung','consent',tq('Eine einwilligungsfähige Person lehnt nach verständlicher Information eine Maßnahme ab. Was tust du?','+Entscheidung respektieren und Gründe erfragen ~ Ablehnung ist Teil der Selbstbestimmung.','+Folgen, Alternativen und Dokumentation klären ~ Eine informierte Entscheidung soll möglich bleiben.','-Zwang allein wegen einer unvernünftig wirkenden Wahl ~ Das ist keine ausreichende Grundlage.','-Zustimmung der Familie hebt die Ablehnung auf ~ Nicht bei einwilligungsfähiger Person.')],
 ['Angehörigengespräch','ethics',tq('Eine Angehörige antwortet ständig für den auskunftsfähigen Patienten. Was ist angemessen?','+Den Patienten direkt nach seinen Wünschen fragen ~ Er ist die zentrale Bezugsperson.','+Beteiligung der Angehörigen mit ihm abstimmen ~ Vertraulichkeit und Unterstützung werden verbunden.','-Nur mit der Angehörigen weiterreden ~ Das übergeht den Patienten.','-Angehörige immer grundsätzlich ausschließen ~ Gewünschte Unterstützung kann hilfreich sein.')],
 ['Kultursensibilität','ethics',tq('Was ist kultursensible Kommunikation?','+Individuelle Wünsche zu Pflege und Religion erfragen ~ Herkunft erlaubt keine sicheren Rückschlüsse.','+Verständliche Kommunikation und gleichberechtigten Zugang ermöglichen ~ Bedürfnisse werden konkret berücksichtigt.','-Alle Menschen einer Herkunft gleich behandeln ~ Das verkennt individuelle Unterschiede.','-Eigene Vorstellungen als allein richtig durchsetzen ~ Das missachtet die Perspektive der Person.')],
 ['Beratung planen','law',tq('Was sollte vor einer Schulung geklärt werden?','+Vorwissen, Lernziel und aktuelle Belastbarkeit ~ Das Angebot muss passen.','+Sprache, Motivation und praktische Möglichkeiten ~ Umsetzung hängt vom Kontext ab.','-Nur die Zahl der Folien ~ Sie beschreibt keinen Lernbedarf.','-Möglichst viele Fachbegriffe einsetzen ~ Das kann Verständnis erschweren.')],
 ['Schulung evaluieren','teach',tq('Wie prüfst du den Erfolg einer Insulinschulung?','+Die Person demonstriert die vereinbarte Injektion ~ Handlungsfähigkeit wird sichtbar.','+Sie erläutert das Vorgehen bei Unterzuckerung ~ Der Notfallplan muss verstanden sein.','-Nur fragen, ob das Heft gefällt ~ Das misst nicht das Lernziel.','-Anwesenheit gilt automatisch als Kompetenznachweis ~ Teilnahme und Können unterscheiden sich.')],
 ['Schlechte Nachricht','law',tq('Nach einer belastenden Diagnose schweigt die Person und weint. Was passt?','+Zeit lassen und Gesprächsbereitschaft anbieten ~ Emotionale Verarbeitung braucht Raum.','+Fragen, was sie jetzt braucht ~ Unterstützung wird individuell.','-Sofort alle Informationen ohne Pause vortragen ~ Das kann überfordern.','-Mit „Andere haben es schlimmer“ relativieren ~ Das entwertet das Erleben.')],
 ['Deeskalation','law',tq('Eine angespannte Person wird laut. Welche Handlungen sind geeignet?','+Ruhig sprechen, Abstand und sicheren Rückzug beachten ~ Sicherheit und Beziehung werden verbunden.','+Auslöser und Bedürfnisse erfragen, Hilfe früh organisieren ~ Das kann Anspannung vermindern.','-Drohungen und körperliche Nähe erzwingen ~ Das kann eskalieren.','-Jede Angst als Absicht zur Gewalt interpretieren ~ Risiko muss konkret beurteilt werden.')],
 ['Beschwerde','law',tq('Eine Patientin beschwert sich über Schmerzen nach verzögerter Hilfe. Was tust du?','+Aktuellen Bedarf zuerst beurteilen ~ Versorgung darf nicht weiter verzögert werden.','+Beschwerde ernst nehmen und nachvollziehbar bearbeiten ~ Rückmeldung kann Qualität verbessern.','-Sofort Schuld bei ihr suchen ~ Das löst das Problem nicht.','-Absolute Fehlerfreiheit versprechen ~ Das ist nicht verlässlich.')],
 ['Nähe und Distanz','ethics',tq('Was kennzeichnet professionelle Beziehungsgestaltung?','+Empathie mit klarer beruflicher Rolle ~ Zugewandtheit und Grenzen gehören zusammen.','+Abhängigkeiten und eigene Gefühle reflektieren ~ Das schützt die Zusammenarbeit.','-Private Bedürfnisse durch die Person erfüllen lassen ~ Das verschiebt den Beziehungszweck.','-Gefühle grundsätzlich ignorieren ~ Sie sind für das Erleben bedeutsam.')],
 ['Ethisches Dilemma','ethics',tq('Welche Schritte helfen in einer ethischen Fallbesprechung?','+Fakten, Wünsche und konkurrierende Werte klären ~ Das schafft eine gemeinsame Grundlage.','+Optionen und Folgen interprofessionell abwägen ~ Die Entscheidung soll begründbar sein.','-Die lauteste Meinung gilt automatisch ~ Lautstärke ist kein ethisches Argument.','-Die Sicht der betroffenen Person weglassen ~ Sie ist zentral.')],
 ['Angehörigenbelastung','law',tq('Eine pflegende Ehefrau berichtet Schlafmangel und Erschöpfung. Was passt?','+Belastungen und vorhandene Unterstützung erfragen ~ Der Entlastungsbedarf wird konkret.','+Geeignete Beratungs- und Entlastungsangebote vermitteln ~ Unterstützung kann Überlastung vermindern.','-Mehr Durchhaltevermögen verlangen ~ Das übersieht den Bedarf.','-Ohne Zustimmung alle persönlichen Details weitergeben ~ Vertraulichkeit ist zu beachten.')],
 ['Kinder beteiligen','each',tq('Welche Kommunikation unterstützt ein Schulkind im Krankenhaus?','+Direkt und altersgerecht erklären ~ Das Kind wird einbezogen.','+Fragen und Wünsche auch unabhängig von den Eltern wahrnehmen ~ Die eigene Perspektive ist bedeutsam.','-Nur Erwachsenen jede Information geben ~ Das Kind bleibt unbeteiligt.','-Entscheidungen anbieten, die tatsächlich nicht möglich sind ~ Scheinwahl schadet Vertrauen.')]
]);
kb(3,[
 ['Delegation','law,reserved',tq('Welche Faktoren sind vor der Delegation einer Maßnahme zu prüfen?','+Qualifikation, aktuelle Fähigkeiten und Situation ~ Die Aufgabe muss sicher übernommen werden können.','+Klarer Auftrag, Anleitung und erforderliche Überwachung ~ Verantwortung endet nicht mit der Zuteilung.','-Nur die freie Zeit der Person ~ Zeit ersetzt keine Kompetenz.','-Delegation hebt alle Vorbehaltsregelungen auf ~ Gesetzliche Grenzen gelten weiter.')],
 ['Vorbehaltsaufgaben','reserved',tq('Welche Tätigkeiten fallen unter § 4 PflBG?','+Pflegebedarf erheben und feststellen sowie Pflege planen ~ Das gehört zu den vorbehaltenen Bereichen.','+Pflegeprozess organisieren, steuern und Pflegequalität evaluieren ~ Prozess- und Qualitätsverantwortung sind geschützt.','-Jede einzelne Grundpflegehandlung ausschließlich ~ Nicht jede Einzelhandlung ist eine Vorbehaltsaufgabe.','-Ärztliche Diagnose und Arzneiverordnung ~ Das sind keine dort benannten Pflegevorbehaltsaufgaben.')],
 ['Unklare Anordnung','law,medicine',tq('Eine Medikamentenanordnung ist unleserlich. Wie gehst du vor?','+Vor der Gabe mit der zuständigen verordnenden Stelle klären ~ Raten gefährdet die Sicherheit.','+Klärung und gültige Anordnung nachvollziehbar machen ~ Das Team braucht eine eindeutige Grundlage.','-Die wahrscheinlichste Dosis schätzen ~ Das ist unsicher.','-Die alte Dosis ungeprüft übernehmen ~ Der aktuelle Auftrag könnte abweichen.')],
 ['Übernahmeverantwortung','law',tq('Du sollst eine dir nicht vertraute invasive Maßnahme allein durchführen. Was ist angemessen?','+Eigene Kompetenzgrenze benennen und Unterstützung organisieren ~ Sichere Durchführung muss möglich sein.','-Die Anordnung verpflichtet unabhängig von Qualifikation ~ Auch Übernahme und Durchführung sind zu verantworten.','-Mit einem kurzen Blick in ein Video jede Einweisung ersetzen ~ Das belegt keine sichere Kompetenz.','-Die Person ohne weitere Organisation unversorgt lassen ~ Geeignete Versorgung muss ermöglicht werden.')],
 ['SBAR','sbar',tq('Welche Bestandteile gehören zu SBAR?','+Situation und Hintergrund ~ Sie ordnen das aktuelle Problem ein.','+Einschätzung und Empfehlung beziehungsweise Bitte ~ Der Handlungsbedarf wird klar.','-Schuldige und Bestrafung ~ Das ist kein SBAR-Bestandteil.','-Nur eine lange Diagnosenliste ~ Das nennt den aktuellen Bedarf nicht ausreichend.')],
 ['Dringliche Übergabe','sbar',tq('Welche Übergabe ist bei akuter Verschlechterung am hilfreichsten?','+Konkrete Veränderung, aktuelle Werte und klarer Unterstützungsbedarf ~ Die Dringlichkeit wird verständlich.','-„Irgendwie ist alles komisch“, ohne weitere Angaben ~ Das lässt zu viele Fragen offen.','-Nur frühere Routinewerte ~ Der aktuelle Zustand fehlt.','-Eine Diagnose als sicher ausgeben, obwohl ungeklärt ~ Beobachtung und Vermutung müssen getrennt bleiben.')],
 ['Closed Loop','law,sbar',tq('Was verbessert die Sicherheit mündlicher Teamaufträge im Notfall?','+Auftrag wiederholen und bestätigen lassen ~ Missverständnisse können auffallen.','+Erledigung oder Hindernisse rückmelden ~ Das Team kennt den Stand.','-Alle rufen gleichzeitig ohne Zuordnung ~ Aufgaben bleiben unklar.','-Unverstandene Aufträge still ausführen ~ Fehler werden wahrscheinlicher.')],
 ['Händehygiene','hygiene',tq('Welche Situationen gehören zu den fünf Momenten der Händehygiene?','+Vor einer aseptischen Tätigkeit ~ Schutz vor Keimeintrag ist erforderlich.','+Nach Kontakt mit der unmittelbaren Patientenumgebung ~ Hände können dabei kontaminiert werden.','-Nur nach sichtbar schmutzigen Tätigkeiten ~ Weitere Indikationen bestehen.','-Handschuhe machen alle Momente überflüssig ~ Sie ersetzen die Händehygiene nicht.')],
 ['Handschuhe','hygiene',tq('Was ist bei medizinischen Einmalhandschuhen richtig?','+Indikationsgerecht verwenden und rechtzeitig wechseln ~ Kontamination kann übertragen werden.','+Händehygiene bleibt nach Indikation erforderlich ~ Handschuhe sind kein vollständiger Ersatz.','-Mit denselben Handschuhen mehrere Personen versorgen ~ Das kann Keime übertragen.','-Nach Ausziehen sind Hände garantiert keimfrei ~ Eine Kontamination ist möglich.')],
 ['Aseptik','hygiene',tq('Vor einer aseptischen Handlung wurde ein unsteriler Gegenstand berührt. Was folgt?','+Die notwendige Asepsis vor Beginn wiederherstellen ~ Kontamination darf nicht eingebracht werden.','-Den Kontakt ignorieren, weil Handschuhe getragen werden ~ Auch Handschuhe können kontaminiert sein.','-Nur schneller arbeiten ~ Geschwindigkeit beseitigt Keime nicht.','-Den Fehler erst nach Durchführung melden ~ Prävention ist vor der Handlung möglich.')],
 ['Medikamentensicherheit','medicine',tq('Welche Prüfungen unterstützen sichere Arzneigabe?','+Person, Wirkstoff, Dosis, Zeitpunkt und Applikationsweg ~ Eine systematische Prüfung vermindert Verwechslungen.','+Allergien, Kontraindikationen und aktuelle Situation ~ Die Verordnung muss zur Person passen.','-Zimmernummer als einziges Identifikationsmerkmal ~ Verwechslungen bleiben möglich.','-Alle Tabletten grundsätzlich zerkleinern ~ Darreichungsformen können ungeeignet sein.')],
 ['Beinahefehler','medicine,law',tq('Eine Medikamentenverwechslung fällt vor der Gabe auf. Was ist sinnvoll?','+Gabe stoppen und sichere Zuordnung herstellen ~ Ein Schaden soll verhindert werden.','+Nach lokalem Meldesystem Ursachen bearbeiten ~ Aus Beinahefehlern kann gelernt werden.','-Nichts melden, weil kein Schaden entstand ~ Ursachen bleiben dann unverändert.','-Nur einzelne Personen beschämen ~ Das behindert eine lernende Sicherheitskultur.')],
 ['Interprofessionelle Kooperation','law',tq('Welche Zusammenarbeit passt bei neuem Dysphagieverdacht?','+Pflegebeobachtungen mit ärztlichem und schlucktherapeutischem Team teilen ~ Mehrere Fachperspektiven sind nötig.','+Ernährungs- und Medikamentenweg gemeinsam abstimmen ~ Sichere Versorgung geht über eine Einzelmaßnahme hinaus.','-Ohne Abklärung jede Kostform beliebig festlegen ~ Der Bedarf ist individuell.','-Nur eine Fachgruppe darf Beobachtungen äußern ~ Relevante Beobachtungen gehören ins Team.')],
 ['Entlassungsmanagement','law,standards',tq('Was gehört vor Entlassung einer unterstützungsbedürftigen Person zur Koordination?','+Medikamente, Hilfsmittel und Anschlussversorgung klären ~ Versorgungslücken sollen vermieden werden.','+Verständnis und tatsächliche Umsetzungsmöglichkeiten prüfen ~ Ein Papierplan allein reicht nicht.','-Erst nach Entlassung nach Unterstützung fragen ~ Das kann unnötige Lücken verursachen.','-Die Familie grundsätzlich als jederzeit verfügbar annehmen ~ Belastbarkeit und Zustimmung sind zu klären.')],
 ['Einarbeitung','law',tq('Eine neue Kollegin kennt ein Medizinprodukt noch nicht. Was ist angemessen?','+Einweisung und sichere Nutzung vor selbstständiger Anwendung klären ~ Gerätekompetenz ist erforderlich.','+Bedienhinweise und lokale Zuständigkeiten beachten ~ Das unterstützt sichere Prozesse.','-Die Verpackung zu kennen reicht ~ Das beweist keine Anwendungskompetenz.','-Ohne Anleitung an der Person ausprobieren ~ Das ist unsicher.')],
 ['Teamkonflikt','law',tq('Im Team gibt es Streit über wiederholte verspätete Schmerzmittelgaben. Wie gehst du vor?','+Aktuelle Versorgung sichern und sachliche Daten sammeln ~ Bedarf und Prozessproblem werden getrennt bearbeitet.','+Zuständigkeiten und Hindernisse gemeinsam klären ~ So können Abläufe verbessert werden.','-Den Konflikt vor der Patientin austragen ~ Das belastet und löst ihn selten.','-Nur persönliche Schuld vermuten ~ Systemische Ursachen können übersehen werden.')],
 ['Priorisierung','abcde,law',tq('Gleichzeitig klingelt eine Person wegen frischer Atemnot und eine wegen einer Decke. Was ist richtig?','+Atemnot zuerst beurteilen und Unterstützung organisieren ~ Potenzielle Vitalgefährdung hat Vorrang.','+Den anderen Bedarf passend delegieren oder rückmelden ~ Auch weniger dringliche Bedürfnisse bleiben relevant.','-Nach Zimmernummer sortieren ~ Das bildet Dringlichkeit nicht ab.','-Erst alle Routinearbeiten abschließen ~ Akute Gefahr darf nicht warten.')],
 ['Sichere Übergänge','sbar,law',tq('Was ist beim Stationswechsel besonders wichtig?','+Aktueller Zustand, Risiken und noch offene Aufträge ~ Kontinuität braucht konkrete Information.','+Medikations- und Versorgungsplan abgleichen ~ Übergänge sind fehleranfällig.','-Nur den Entlassungsbrief ungelesen mitgeben ~ Offene Risiken können unklar bleiben.','-Ausschließlich berichten, dass „alles stabil“ sei ~ Der Verlauf und Unterstützungsbedarf fehlen.')],
 ['Aufgabenverteilung','law,reserved',tq('Eine Hilfskraft soll eine vollständige Pflegeplanung eigenverantwortlich erstellen. Was ist zu beachten?','+Pflegeplanung gehört zu den vorbehaltenen Aufgaben ~ Die Verantwortung liegt bei entsprechend qualifizierten Pflegefachpersonen.','+Beobachtungen anderer Teammitglieder können einfließen ~ Zusammenarbeit bleibt möglich.','-Eine beliebige Aufgabenliste hebt die Vorbehaltsregel auf ~ Interne Vorgaben ersetzen das Gesetz nicht.','-Hilfskräfte dürfen keinerlei Beobachtung berichten ~ Das wäre fachlich unsinnig.')],
 ['Dokumentierte Wirkung','law,medicine',tq('Nach einer Bedarfsanalgesie ist bei Übergabe besonders wichtig:','+Ausgangsschmerz, Mittel, Zeitpunkt, Wirkung und Nebenwirkungen ~ Die nächste Schicht muss den Verlauf kennen.','-Nur dass eine Tablette gegeben wurde ~ Wirkung und Sicherheit fehlen.','-Die Wirkung ohne Nachfrage als gut markieren ~ Das ist kein verlässliches Ergebnis.','-Weitere Beschwerden bis zur nächsten Schicht verschweigen ~ Relevante Informationen müssen weitergegeben werden.')]
]);
kb(4,[
 ['Einwilligung','consent',tq('Welche Aussage zur Einwilligung ist richtig?','+Sie kann grundsätzlich jederzeit widerrufen werden ~ Selbstbestimmung besteht weiter.','-Eine Unterschrift erlaubt jede spätere Maßnahme ~ Einwilligung ist maßnahmenbezogen.','-Angehörige entscheiden immer automatisch ~ Eine Berechtigung muss bestehen.','-Aufklärung und Zustimmung sind immer entbehrlich ~ Es gelten gesetzliche Voraussetzungen.')],
 ['Einwilligungsfähigkeit','consent',tq('Was ist bei Einwilligungsfähigkeit zu beachten?','+Sie ist bezogen auf die konkrete Entscheidung zu beurteilen ~ Verständnis und Folgenabschätzung sind relevant.','+Eine Demenzdiagnose allein entscheidet die Frage nicht ~ Fähigkeiten können unterschiedlich ausgeprägt sein.','-Ein hoher Pflegegrad bedeutet automatisch Unfähigkeit ~ Das ist keine ausreichende Begründung.','-Wer anderer Meinung ist, ist nicht einwilligungsfähig ~ Abweichende Wünsche sind kein Beweis.')],
 ['Aufklärung','consent,law',tq('Vor einer invasiven Maßnahme zeigt die Person fehlendes Verständnis. Was folgt?','+Klärung mit der zuständigen aufklärenden Stelle ~ Eine informierte Entscheidung muss möglich sein.','-Trotzdem durchführen, weil ein Formular unterschrieben ist ~ Eine Unterschrift ersetzt kein Verständnis.','-Nur die Angehörigen beruhigen ~ Die Person selbst bleibt zentral.','-Eigene ungesicherte Informationen als sichere Alternative geben ~ Zuständigkeit und fachliche Richtigkeit sind wichtig.')],
 ['Freiheitsentziehung','restraint',tq('Welche Fragen sind vor einem Bettgitter relevant?','+Wille, Einwilligungsfähigkeit und tatsächliche Wirkung ~ Nicht jede technische Maßnahme ist gleich zu bewerten.','+Alternativen und passende rechtliche Grundlage ~ Freiheitsentziehung erfordert besondere Prüfung.','-Die Angehörigenzustimmung reicht immer allein ~ Das ist keine pauschale Rechtsgrundlage.','-Personalmangel rechtfertigt automatisch jede Fixierung ~ Das ist unzulässig.')],
 ['Betreuung','consent,restraint',tq('Eine Betreuung ist eingerichtet. Was ist richtig?','+Aufgabenkreis und konkrete Entscheidungsbefugnis prüfen ~ Betreuung ist kein unbegrenzter Blankoscheck.','+Wünsche und Fähigkeiten der Person weiterhin berücksichtigen ~ Betreuung hebt Selbstbestimmung nicht pauschal auf.','-Alle eigenen Entscheidungen der Person sind unwirksam ~ Das folgt nicht aus Betreuung.','-Jeder Angehörige ist automatisch Betreuer ~ Eine Befugnis muss bestehen.')],
 ['Schweigepflicht','law,ethics',tq('Eine Nachbarin fragt telefonisch nach der Diagnose. Was ist angemessen?','+Ohne passende Berechtigung keine Gesundheitsdaten mitteilen ~ Vertraulichkeit ist zu schützen.','+Identität und Freigabe nach Standard klären ~ Telefonische Angaben sind nicht automatisch vertrauenswürdig.','-Auskunft geben, wenn die Anruferin freundlich ist ~ Freundlichkeit begründet keine Befugnis.','-Alle Details im Flur besprechen ~ Dritte könnten mithören.')],
 ['Datenschutz','ethics,law',tq('Welche Handlungen schützen Gesundheitsdaten?','+Nur erforderliche Daten an berechtigte Stellen weitergeben ~ Zweck und Berechtigung sind zu prüfen.','+Bildschirme und Unterlagen vor unbefugtem Zugriff schützen ~ Auch im Alltag entstehen Zugriffsrisiken.','-Passwörter mit allen teilen ~ Das verhindert nachvollziehbare Zugriffe.','-Patientendaten in private Chats kopieren ~ Dafür fehlt regelmäßig eine sichere Grundlage.')],
 ['Dokumentation','law',tq('Welche Dokumentation ist fachlich nachvollziehbar?','+Zeitnahe konkrete Beobachtungen, Maßnahmen und Wirkung ~ Verlauf und Entscheidungen werden verständlich.','+Nachträge als solche kenntlich machen ~ Der ursprüngliche Verlauf muss erkennbar bleiben.','-Fehlerhafte Einträge unsichtbar überschreiben ~ Änderungen müssen nachvollziehbar sein.','-Abwertungen statt beobachtbarem Verhalten notieren ~ Das ist unpräzise und unprofessionell.')],
 ['Qualitätsdimensionen','standards,law',tq('Welche Zuordnung passt zu Donabedians Qualitätsdimensionen?','+Qualifikation und Ausstattung: Strukturqualität ~ Sie bilden Rahmenbedingungen.','+Durchführung: Prozessqualität; Wirkung: Ergebnisqualität ~ Ablauf und Ergebnis sind zu unterscheiden.','-Jede Materialbestellung beweist Ergebnisqualität ~ Sie belegt noch keine Wirkung.','-Ein ungünstiges Ergebnis beweist automatisch einen Fehler ~ Auch andere Faktoren beeinflussen Ergebnisse.')],
 ['Expertenstandard','standards',tq('Wie wird ein Expertenstandard sinnvoll angewandt?','+Auf Einrichtung und individuelle Versorgung fachlich übertragen ~ Kriterien müssen praktisch umgesetzt werden.','+Umsetzung und Ergebnisse überprüfen ~ Ein Standard braucht Evaluation.','-Den Text unverändert für jede Person als Pflegeplan kopieren ~ Individuelle Beurteilung fehlt dann.','-Einmal kaufen genügt als Qualitätsnachweis ~ Anwendung und Wirkung müssen folgen.')],
 ['Audit','standards',tq('Was ist der Zweck eines Pflegeaudits?','+Umsetzung definierter Qualitätskriterien systematisch prüfen ~ Stärken und Lücken werden sichtbar.','+Verbesserungsmaßnahmen aus Ergebnissen ableiten ~ Prüfung soll Versorgung verbessern.','-Nur möglichst viele Formulare zählen ~ Das sagt wenig über Qualität.','-Eine schlechte Zahl immer einzelnen Personen zuschreiben ~ Ursachen können im System liegen.')],
 ['Risikomanagement','law',tq('Welche Bearbeitung eines Medikationsvorfalls ist angemessen?','+Aktuelle Gefährdung versorgen und Ursache analysieren ~ Sicherheit und Lernen gehören zusammen.','+Verbindliche Verbesserungen und Wirksamkeitskontrolle ~ Ursachen sollen nicht fortbestehen.','-Nur einen Schuldigen benennen und abschließen ~ Das verändert den Prozess nicht zuverlässig.','-Jeden Vorfall geheim halten ~ Wiederholungsrisiken bleiben unentdeckt.')],
 ['Beschwerdemanagement','law',tq('Welche Merkmale kennzeichnen ein gutes Beschwerdeverfahren?','+Erreichbare Ansprechpersonen und nachvollziehbare Bearbeitung ~ Rückmeldungen sollen möglich sein.','+Rückmeldung und Nutzung für Verbesserungen ~ Beschwerden liefern Hinweise auf Probleme.','-Beschwerden dürfen Versorgung verschlechtern ~ Benachteiligung ist unprofessionell.','-Nur mündliche Kritik grundsätzlich ignorieren ~ Auch sie kann relevant sein.')],
 ['Notfall und Einwilligung','consent',tq('Eine unaufschiebbare Maßnahme kann nicht rechtzeitig mit einer berechtigten Person geklärt werden. Was ist rechtlich relevant?','+Der mutmaßliche Wille und bekannte Festlegungen ~ § 630d regelt eine Notfallausnahme.','-Jede Notlage erlaubt beliebige Maßnahmen ~ Die Ausnahme ist begrenzt.','-Ein bekannter entgegenstehender Wille ist immer bedeutungslos ~ Er muss berücksichtigt werden.','-Bis zu einer Unterschrift jede Hilfe unterlassen ~ Das kann die Person gefährden.')],
 ['Patientenverfügung','consent,law',tq('Was ist bei einer vorliegenden Patientenverfügung zu prüfen?','+Ob sie zur aktuellen Situation und Maßnahme passt ~ Die konkrete Anwendbarkeit ist entscheidend.','+Bekannter Wille und zuständige Vertretung ~ Die Entscheidung muss sauber geklärt werden.','-Jedes Dokument verbietet automatisch jede Pflege ~ Inhalt und Situation unterscheiden sich.','-Angehörige dürfen sie ohne Weiteres ignorieren ~ Der Wille ist rechtlich bedeutsam.')],
 ['Wirtschaftlichkeit','law,ethics',tq('Wie lassen sich Ressourcenverantwortung und gute Pflege verbinden?','+Material bedarfsgerecht einsetzen und Verschwendung vermeiden ~ Versorgung bleibt am Bedarf orientiert.','+Wirksame sichere Abläufe gemeinsam verbessern ~ Qualität und Ressourcen können zusammen gedacht werden.','-Notwendige Versorgung pauschal streichen ~ Das gefährdet Rechte und Sicherheit.','-Sicherheitsprodukte ungeprüft mehrfach verwenden ~ Kostendruck hebt Vorgaben nicht auf.')],
 ['Versorgungskoordination','law',tq('Welche Information unterstützt die Wahl einer Anschlussversorgung?','+Konkreter Hilfebedarf, Wünsche und vorhandene Unterstützung ~ Eine passende Versorgung braucht diese Angaben.','+Tatsächliche Erreichbarkeit und Verfügbarkeit von Angeboten ~ Ein theoretisches Angebot reicht nicht.','-Nur der Wunsch der Einrichtung nach freiem Bett ~ Das ersetzt keine Bedarfsbeurteilung.','-Angehörigenhilfe ungefragt voraussetzen ~ Bereitschaft und Möglichkeiten sind zu klären.')],
 ['Qualitätsindikatoren','standards',tq('Eine Station hat mehr Stürze gemeldet. Was ist vor einer Bewertung zu prüfen?','+Risikoprofil, Bezugsgröße und Meldepraxis ~ Rohzahlen können irreführen.','+Schwere, Ursachen und Präventionsprozesse ~ Die Zahl allein erklärt den Verlauf nicht.','-Mehr Meldungen beweisen immer schlechtere Pflege ~ Auch bessere Erfassung kann beitragen.','-Zur Verbesserung einfach weniger melden ~ Das verschleiert Risiken.')],
 ['Rechte im Alltag','consent,ethics',tq('Eine einwilligungsfähige Person möchte später aufstehen als der Stationsplan. Was passt?','+Wünsche und notwendige Versorgung gemeinsam abstimmen ~ Selbstbestimmung gilt auch im Alltag.','-Der Stationsplan hebt alle Wünsche auf ~ Organisation ist kein pauschaler Vorrang.','-Ohne Gespräch sofort vollständig versorgen ~ Einwilligung und Beteiligung fehlen.','-Jede abweichende Routine ist automatisch gefährlich ~ Risiken müssen konkret begründet werden.')],
 ['Sicherheitsbedenken','law,ethics',tq('Die Personalausstattung erlaubt eine notwendige Überwachung nicht sicher. Was ist angemessen?','+Konkretes Risiko an zuständige Leitung eskalieren und Versorgung organisieren ~ Sicherheitsprobleme brauchen eine Lösung.','+Situation und veranlasste Schritte sachlich nachvollziehbar festhalten ~ Risiken und Reaktionen müssen erkennbar sein.','-Unbeobachtete Versorgung als erfolgt dokumentieren ~ Das ist falsch und gefährlich.','-Alle Risiken stillschweigend übernehmen ~ Dadurch wird keine sichere Organisation hergestellt.')]
]);
kb(5,[
 ['Evidenzbasierte Pflege','ebp',tq('Welche drei Perspektiven werden bei evidenzbasierter Versorgung verbunden?','+Beste verfügbare Forschung und klinische Expertise ~ Beides trägt zu begründeten Entscheidungen bei.','+Wünsche und Werte der betroffenen Person ~ Evidenz muss zur Person passen.','-Nur die neueste Schlagzeile ~ Aktualität allein garantiert keine Qualität.','-Allein Gewohnheit der Einrichtung ~ Routine ersetzt keine kritische Prüfung.')],
 ['PICO','ebp',tq('Wozu dient eine PICO-Frage?','+Eine beantwortbare Frage zu Population, Intervention, Vergleich und Ergebnis strukturieren ~ Das erleichtert gezielte Recherche.','-Eine Diagnose ohne Untersuchung stellen ~ Das ist kein Zweck von PICO.','-Jede Pflegehandlung automatisch verbieten ~ Das Schema bewertet keine Handlung allein.','-Ein Studienergebnis ungeprüft auf alle übertragen ~ Übertragbarkeit ist gesondert zu prüfen.')],
 ['Recherche','ebp',tq('Welche Recherche ist für eine fachliche Frage geeignet?','+Gezielte Suchbegriffe und passende Datenbanken nutzen ~ Die Suche soll systematisch nachvollziehbar sein.','+Aktuelle Leitlinien und methodisch passende Studien prüfen ~ Quellenqualität und Fragestellung zählen.','-Nur Beiträge mit vielen Likes verwenden ~ Beliebtheit ist kein Evidenzmaß.','-Nach dem ersten passenden Satz abbrechen ~ Gegenbefunde und Qualität könnten fehlen.')],
 ['Quellenbewertung','ebp',tq('Welche Fragen helfen bei der Bewertung einer Gesundheitsinformation?','+Wer ist verantwortlich, welche Quellen und Interessen bestehen? ~ Herkunft und Interessenkonflikte sind relevant.','+Wie aktuell und methodisch begründet sind die Aussagen? ~ Aktualität allein reicht aber nicht aus.','-Ist die Seite besonders bunt? ~ Gestaltung beweist keine Richtigkeit.','-Bestätigt sie meine Meinung? ~ Das kann Bestätigungsfehler fördern.')],
 ['Studienkritik','ebp',tq('Was sollte vor der Übernahme eines Studienergebnisses geprüft werden?','+Verzerrungsrisiko und methodische Qualität ~ Studien können systematische Fehler enthalten.','+Passung von Population und Versorgungskontext ~ Ergebnisse sind nicht immer übertragbar.','-Nur die Zahl der Presseberichte ~ Das bewertet die Methodik nicht.','-Ein statistisch signifikanter Wert garantiert großen Nutzen ~ Klinische Relevanz ist gesondert zu prüfen.')],
 ['Randomisierung','ebp',tq('Welchen Zweck hat eine zufällige Gruppenzuteilung in einer Studie?','+Bekannte und unbekannte Störfaktoren möglichst ausgleichen ~ Dadurch wird die Vergleichbarkeit verbessert.','-Sie garantiert fehlerfreie Ergebnisse ~ Weitere Verzerrungen sind möglich.','-Sie ersetzt die Einwilligung ~ Forschung braucht weiterhin ethische Voraussetzungen.','-Sie macht jede Verblindung unnötig ~ Das sind unterschiedliche Schutzmechanismen.')],
 ['Korrelation','ebp',tq('Eine Studie findet einen Zusammenhang zwischen zwei Merkmalen. Was folgt daraus?','+Kausalität ist damit allein nicht bewiesen ~ Andere Erklärungen sind möglich.','+Studiendesign und Störfaktoren müssen betrachtet werden ~ Sie beeinflussen die Interpretation.','-Das erste Merkmal verursacht sicher das zweite ~ Korrelation genügt dafür nicht.','-Jeder Zusammenhang ist automatisch klinisch bedeutsam ~ Größe und Bedeutung sind zu prüfen.')],
 ['Relative und absolute Effekte','ebp',tq('Ein Risiko sinkt von 10 % auf 5 %. Welche Aussagen stimmen?','+Die absolute Risikoreduktion beträgt 5 Prozentpunkte ~ 10 minus 5 ergibt 5 Prozentpunkte.','+Die relative Risikoreduktion beträgt 50 % ~ Bezogen auf 10 % halbiert sich das Risiko.','-Die absolute Reduktion beträgt 50 Prozentpunkte ~ Das verwechselt absolute und relative Größen.','-Die Behandlung verhindert jedes Ereignis ~ Es bleibt ein Risiko von 5 %.')],
 ['Leitlinien','ebp,standards',tq('Wie gehst du mit einer Leitlinienempfehlung um?','+Gültigkeit, Evidenz und individuelle Anwendbarkeit prüfen ~ Leitlinien unterstützen begründete Entscheidungen.','+Abweichungen fachlich begründen und abstimmen ~ Die Person kann besondere Bedürfnisse haben.','-Jede Empfehlung passt unverändert zu jedem Menschen ~ Kontext und Präferenzen bleiben wichtig.','-Ein abgelaufenes Dokument garantiert aktuelle Therapie ~ Die Aktualität muss geprüft werden.')],
 ['Transfer','ebp,law',tq('Ein neues Verfahren soll auf Station eingeführt werden. Was gehört dazu?','+Nutzen, Risiken und Voraussetzungen bewerten ~ Die Einführung braucht eine fachliche Grundlage.','+Einweisung, Pilotierung und Evaluation planen ~ Wirksamkeit im Alltag muss geprüft werden.','-Sofort sämtliche Standards ohne Abstimmung ersetzen ~ Das kann Sicherheit gefährden.','-Nur den Produktprospekt als Nachweis nutzen ~ Werbematerial reicht nicht aus.')],
 ['Reflexion','law',tq('Was kennzeichnet eine hilfreiche berufliche Reflexion?','+Situation, eigenes Handeln und Folgen kritisch betrachten ~ Lernen wird konkret.','+Alternativen und nächste Schritte ableiten ~ Reflexion soll zukünftiges Handeln verbessern.','-Nur sich selbst pauschal verurteilen ~ Das erzeugt keine konkrete Verbesserung.','-Alle Schwierigkeiten ausschließlich anderen zuschreiben ~ Der eigene Einfluss bleibt ungeprüft.')],
 ['Feedback','law',tq('Welches Feedback unterstützt Lernen?','+Konkretes beobachtetes Verhalten und Wirkung beschreiben ~ Rückmeldung wird nachvollziehbar.','+Eine umsetzbare Verbesserung vereinbaren ~ Das schafft einen nächsten Schritt.','-Die ganze Person abwerten ~ Das ist wenig hilfreich und verletzend.','-Fehler vor allen verspotten ~ Das behindert eine sichere Lernkultur.')],
 ['Kompetenzentwicklung','law',tq('Du bemerkst Unsicherheit bei der Versorgung eines Ports. Was ist professionell?','+Lernbedarf benennen und qualifizierte Anleitung suchen ~ Kompetenzgrenzen werden verantwortet.','+Nach Einweisung sicheres Handeln überprüfen lassen ~ Wissen und Ausführung müssen zusammenpassen.','-Unsicherheit verbergen und improvisieren ~ Das gefährdet die Person.','-Einmaliges Zuschauen gilt automatisch als Können ~ Das belegt keine sichere Kompetenz.')],
 ['Lebenslanges Lernen','law',tq('Wie planst du eine sinnvolle Fortbildung?','+Lernziel aus konkretem Versorgungsbedarf ableiten ~ Lernen soll eine relevante Lücke schließen.','+Anwendung und späteren Lernerfolg prüfen ~ Teilnahme allein ist kein Transfer.','-Nur möglichst viele Zertifikate sammeln ~ Anzahl beweist keine Kompetenz.','-Nach dem Examen ist jede Fortbildung unnötig ~ Wissen und Anforderungen entwickeln sich weiter.')],
 ['Berufliche Gesundheit','law',tq('Welche Schritte passen bei wiederholter Überlastung?','+Belastungsfaktoren und verfügbare Unterstützung ansprechen ~ Lösungen brauchen individuelle und organisatorische Maßnahmen.','+Pausen, sichere Arbeit und Unterstützungsangebote planen ~ Gesundheit ist eine berufliche Ressource.','-Belastung immer als persönliches Versagen werten ~ Arbeitsbedingungen können wesentlich beitragen.','-Warnzeichen dauerhaft ignorieren ~ Das kann Gesundheit und Sicherheit beeinträchtigen.')],
 ['Moralische Belastung','ethics,law',tq('Du weißt, welche Pflege nötig wäre, kannst sie wegen Rahmenbedingungen nicht umsetzen. Was hilft?','+Ethische und organisatorische Ursachen gemeinsam reflektieren ~ Der Konflikt soll benannt werden.','+Geeignete Fallbesprechung und Leitung einbeziehen ~ Unterstützung kann Handlungsspielraum schaffen.','-Nur schweigend aushalten als Berufsregel ~ Dadurch ändert sich die Belastung nicht.','-Den Ärger an Pflegebedürftigen auslassen ~ Das ist unprofessionell und schädlich.')],
 ['Digitale Informationen','ebp,ethics',tq('Ein KI-System liefert eine überzeugend formulierte Pflegemaßnahme. Wie gehst du vor?','+Quellen, Aktualität und fachliche Richtigkeit prüfen ~ Plausible Sprache garantiert keine korrekten Inhalte.','+Passung zur Person und eigene Verantwortung beachten ~ Die Entscheidung bleibt fachlich zu begründen.','-Ungeprüft übernehmen, weil der Text sicher klingt ~ Fehler können verborgen sein.','-Vertrauliche Daten beliebig eingeben ~ Datenschutz bleibt erforderlich.')],
 ['Nachhaltigkeit','law',tq('Welche Maßnahme verbindet Nachhaltigkeit und Sicherheit?','+Material nur bedarfsgerecht öffnen ~ Unnötiger Abfall kann vermindert werden.','+Vorgaben für Hygiene und Entsorgung einhalten ~ Nachhaltigkeit braucht sichere Umsetzung.','-Sterile Einmalprodukte ungeprüft wiederverwenden ~ Das kann Infektionsrisiken schaffen.','-Notwendige Schutzkleidung generell weglassen ~ Sicherheit bleibt verbindlich.')],
 ['Berufliche Rolle','reserved,ethics',tq('Was gehört zu professionellem Pflegehandeln?','+Eigene Entscheidungen fachlich und ethisch begründen ~ Pflege trägt eigenständige Verantwortung.','+Grenzen erkennen und interprofessionell kooperieren ~ Expertise wird passend genutzt.','-Jede Anordnung unabhängig von Risiken ausführen ~ Verantwortung verlangt Prüfung.','-Nur die eigene Meinung ohne Evidenz gelten lassen ~ Mehrere Wissensperspektiven sind nötig.')],
 ['Lernen fürs Examen','law',tq('Welche Lernhandlung prüft berufliche Handlungskompetenz besonders gut?','+Eine Fallsituation beurteilen und Maßnahmen begründen ~ Wissen wird in Entscheidungen übertragen.','+Fehler analysieren und ähnliche Fälle erneut bearbeiten ~ Rückmeldung unterstützt Lerntransfer.','-Nur Antwortpositionen auswendig lernen ~ Das prüft kein fachliches Verständnis.','-Ein richtiges Quiz gilt als vollständiger Praxisnachweis ~ Eine Übungsrunde ersetzt keine praktische Kompetenzprüfung.')]
]);
