for(const [id,url] of Object.entries({'d-depression':'https://www.nhs.uk/mental-health/conditions/depression-in-adults/overview/','d-schizophrenia':'https://www.nhs.uk/mental-health/conditions/schizophrenia/overview/','d-delir':'https://www.nice.org.uk/guidance/cg103/chapter/Recommendations','d-stroke':'https://www.nhs.uk/conditions/stroke/symptoms/','d-leukaemia':'https://www.nhs.uk/conditions/acute-myeloid-leukaemia/symptoms/'}))trainerSources[id][1]=url;
