function trainerExactMatch(question,selected){return Array.isArray(selected)&&new Set(selected).size===selected.length&&selected.every(i=>Number.isInteger(i)&&i>=0&&i<question.options.length)&&question.options.every((o,i)=>o.correct===selected.includes(i))}
